struct NamedTrainable<'a> {
    name: String,
    trainable: RwkvTrainableRef<'a>,
}

impl NamedTrainable<'_> {
    fn as_trainable(&self) -> RwkvTrainableRef<'_> {
        RwkvTrainableRef {
            name: &self.name,
            ..self.trainable
        }
    }
}

/// Host inputs for one recurrent branch of the fused H/L/loss submission.
/// The branch still accepts materialized residual inputs and upstream output
/// gradients; the next graph layer will replace those host slices with the
/// manager/worker projection buffers directly.
pub struct HierarchosRecurrentBranchInput<'a> {
    pub batch: usize,
    pub steps: usize,
    pub x_sequence: &'a [f32],
    pub token_id_sequence: &'a [u32],
    pub initial_packed_state: &'a [f32],
    pub grad_output_sequence: &'a [f32],
    pub final_packed_state_grad: Option<&'a [f32]>,
    pub schedule: RwkvTbpttSchedule,
}

#[derive(Debug)]
pub struct HierarchosFusedRecurrentLossStepResult {
    pub h: RwkvTbpttTrainStepResult,
    pub l: RwkvTbpttTrainStepResult,
    pub output: TrainStepResult,
    /// This API records H, L, and the output loss into exactly one
    /// `ComputeBatch::submit` call.
    pub queue_submissions: u32,
}

/// One-token integration input for the first projection-coupled recurrent
/// training graph. The caller still supplies the pre-projection base features
/// and loss-side projection gradients, but neither H/L residual input nor H/L
/// upstream gradient is host-materialized: those are assembled from Vulkan
/// projection buffers inside the command graph.
pub struct HierarchosProjectionCoupledTokenInput<'a> {
    pub batch: usize,
    pub h_base_residual: &'a [f32],
    pub l_input_source: &'a [f32],
    pub h_token_ids: &'a [u32],
    pub l_token_ids: &'a [u32],
    pub h_initial_packed_state: &'a [f32],
    pub l_initial_packed_state: &'a [f32],
    pub h_to_context_grad: &'a [f32],
    pub h_halt_grad: &'a [f32],
    pub context_drift_grad: &'a [f32],
    pub l_to_out_grad: &'a [f32],
}

#[derive(Debug)]
pub struct HierarchosProjectionCoupledTokenStepResult {
    pub h: RwkvTbpttTrainStepResult,
    pub l: RwkvTbpttTrainStepResult,
    pub projection_optimizer: RwkvOptimizerStepResult,
    pub projection_parameters: Vec<RwkvParameterSnapshot>,
    pub shared_lm_step: u32,
    pub queue_submissions: u32,
}

/// Device-resident manager pondering input. `h_residual_input` is the manager
/// residual after any L feedback has been applied. The first H transition is
/// real; later candidates start from its device-resident state in an isolated
/// workspace and repeatedly consume the same residual/token features.
pub struct HierarchosManagerHardActInput<'a> {
    pub batch: usize,
    pub steps: usize,
    pub h_residual_input: &'a [f32],
    pub h_token_ids: &'a [u32],
    pub h_initial_packed_state: &'a [f32],
}

#[derive(Debug)]
pub struct HierarchosManagerHardActResult {
    pub halt_probabilities: Vec<f32>,
    pub selected_index: Vec<u32>,
    pub executed_steps: Vec<f32>,
    pub selected_output: Vec<f32>,
    pub selected_packed_state: Vec<f32>,
    pub queue_submissions: u32,
}

/// One-token graph input that closes the final worker-output/language-model
/// loss edge. The manager/context-control gradients remain explicit host seams
/// for the next ACT/interpolation cut, but `l_to_out` is now driven by the real
/// cross-entropy gradient rather than a caller-supplied projection gradient.
pub struct HierarchosLossCoupledTokenInput<'a> {
    pub batch: usize,
    pub enc: &'a [f32],
    pub l_input_source: &'a [f32],
    pub h_token_ids: &'a [u32],
    pub l_token_ids: &'a [u32],
    pub h_initial_packed_state: &'a [f32],
    pub l_initial_packed_state: &'a [f32],
    pub h_to_context_grad: &'a [f32],
    pub h_halt_grad: &'a [f32],
    pub context_drift_grad: &'a [f32],
    pub targets: &'a [u32],
}

#[derive(Debug)]
pub struct HierarchosLossCoupledTokenStepResult {
    pub h: RwkvTbpttTrainStepResult,
    pub l: RwkvTbpttTrainStepResult,
    pub output: TrainStepResult,
    pub projection_optimizer: RwkvOptimizerStepResult,
    pub projection_parameters: Vec<RwkvParameterSnapshot>,
    pub queue_submissions: u32,
}

/// Full one-token hard-ACT manager + worker-refinement + LM-loss graph. Manager
/// pondering, row-local worker refinement, selected-state commitment, clamp
/// adjoints, and the canonical full-model AdamW update remain device-resident;
/// host inputs are now limited to token/state boundaries and explicit future-
/// token adjoints.
pub struct HierarchosWorkerRefinementLossInput<'a> {
    pub batch: usize,
    /// Number of hard-ACT manager candidates, including the first real H step.
    pub h_steps: usize,
    pub shadow_steps: usize,
    pub enc: &'a [f32],
    pub previous_context: &'a [f32],
    pub target_context: &'a [f32],
    pub context_alpha: f32,
    pub h_token_ids: &'a [u32],
    pub l_token_ids: &'a [u32],
    pub h_initial_packed_state: &'a [f32],
    pub l_initial_packed_state: &'a [f32],
    pub l_final_packed_state_grad: Option<&'a [f32]>,
    pub h_to_context_grad: &'a [f32],
    /// Upstream adjoint for `hard_act_depth_straight_through`.
    pub h_depth_grad: &'a [f32],
    /// Future-token adjoint for the hard-selected manager state. This is the
    /// cross-token commitment edge; `None` starts the selected-state path at 0.
    pub h_selected_packed_state_grad: Option<&'a [f32]>,
    pub final_drift_grad: &'a [f32],
    /// Per-row upstream gradient for the averaged commitment cost. Supplying
    /// zeros observes the auxiliary without contributing it to the update.
    pub commitment_cost_grad: &'a [f32],
    pub targets: &'a [u32],
    /// Optional per-row CE source-gradient mass. `None` preserves the legacy
    /// batch mean. Explicit values are intentionally not normalized here so a
    /// token tape can accumulate PyTorch weighted-token numerators and divide
    /// the complete optimizer window exactly once before AdamW.
    pub supervision_weights: Option<&'a [f32]>,
}

/// Raw-token variant of the complete one-token Hierarchos training graph.
///
/// This is the first token-to-loss Vulkan composition seam. The caller no
/// longer supplies a precomputed `enc`: token embedding, learned ROSA mixing,
/// qproj, LTM similarity/top-k/gather/gating, persistent concatenation, and
/// in_proj/GELU are recorded ahead of the existing manager/worker graph. Its
/// device-resident `d(enc)` is then reversed through that same frontend before
/// the one canonical AdamW step.
///
/// Bounded coherent-v9 ROSA state is lane-local: each batch row owns an
/// independent persistent history across calls, and `rosa_reset_lanes` starts
/// selected rows from a fresh segment before the current token is consumed.
pub struct HierarchosRawTokenWorkerRefinementLossInput<'a> {
    pub batch: usize,
    pub h_steps: usize,
    pub shadow_steps: usize,
    pub token_ids: &'a [u32],
    pub rosa_reset_lanes: &'a [u32],
    pub previous_context: &'a [f32],
    pub target_context: &'a [f32],
    pub context_alpha: f32,
    pub h_token_ids: &'a [u32],
    pub l_token_ids: &'a [u32],
    pub h_initial_packed_state: &'a [f32],
    pub l_initial_packed_state: &'a [f32],
    pub l_final_packed_state_grad: Option<&'a [f32]>,
    pub h_to_context_grad: &'a [f32],
    pub h_depth_grad: &'a [f32],
    pub h_selected_packed_state_grad: Option<&'a [f32]>,
    pub final_drift_grad: &'a [f32],
    pub commitment_cost_grad: &'a [f32],
    pub ltm_value_alignment_position: u64,
    pub ltm_value_alignment_mask: Option<&'a [f32]>,
    /// Legacy external-policy override. Packages with a non-zero native
    /// alignment weight ignore this scalar and use the controller above.
    pub ltm_value_alignment_grad: f32,
    pub targets: &'a [u32],
    pub supervision_weights: Option<&'a [f32]>,
}

/// Controls the canonical full-model AdamW gradient window for the complete
/// hard-ACT/worker/loss graph. `Step` preserves the historical one-token
/// behavior. The three accumulation modes let multiple microbatches contribute
/// to the same canonical device-resident full-model gradient registry before one update.
#[derive(Clone, Copy, Debug, Eq, PartialEq)]
pub enum HierarchosFullModelUpdateMode {
    /// Zero the canonical registry, accumulate this graph, and step AdamW.
    Step,
    /// Zero the canonical registry and accumulate this graph without stepping.
    BeginAccumulation,
    /// Preserve existing canonical gradients and add this graph without stepping.
    Accumulate,
    /// Preserve existing canonical gradients, add this graph, then step once.
    FinishAccumulation,
}

impl HierarchosFullModelUpdateMode {
    fn reset_gradient(self) -> bool {
        matches!(self, Self::Step | Self::BeginAccumulation)
    }

    fn step_after(self) -> bool {
        matches!(self, Self::Step | Self::FinishAccumulation)
    }
}

#[derive(Debug)]
pub struct HierarchosWorkerRefinementLossStepResult {
    pub h: RwkvTbpttTrainStepResult,
    pub l: RwkvTbpttTrainStepResult,
    pub output: TrainStepResult,
    pub projection_optimizer: RwkvOptimizerStepResult,
    /// Canonical H/L/projection/out_norm/tied-LM AdamW step. The per-component
    /// optimizer fields above are compatibility views of this same global step.
    pub full_model_optimizer: RwkvOptimizerStepResult,
    pub projection_parameters: Vec<RwkvParameterSnapshot>,
    pub final_drift: Vec<f32>,
    pub commitment_cost: Vec<f32>,
    pub effective_l_steps: Vec<f32>,
    pub grad_enc: Vec<f32>,
    pub grad_previous_context: Vec<f32>,
    pub grad_target_context: Vec<f32>,
    pub manager_halt_probabilities: Vec<f32>,
    pub manager_selected_index: Vec<u32>,
    pub manager_executed_steps: Vec<f32>,
    pub manager_selected_output: Vec<f32>,
    pub manager_selected_packed_state: Vec<f32>,
    pub queue_submissions: u32,
}

/// Chronological snapshots of the per-use RWKV low-rank `g2` scratch gradient.
/// Each entry is captured into independent Vulkan storage before the next
/// recurrent backward use can overwrite the cell scratch tensor.
#[derive(Debug)]
pub struct HierarchosLowRankG2GradientTrace {
    pub h_uses: Vec<Vec<f32>>,
    pub l_uses: Vec<Vec<f32>>,
}

/// Execution precision policy for trainable parameter consumers. The FP32
/// master tensors, AdamW moments, gradients, and SafeTensors checkpoint layout
/// are invariant across policies so a Vulkan-trained package remains directly
/// consumable by PyTorch/CUDA and the native inference runtime.
#[derive(Clone, Copy, Debug, Default, Eq, PartialEq)]
pub enum HierarchosTrainingPrecisionPolicy {
    #[default]
    Fp32,
    /// Store the six RWKV low-rank matrices per recurrent tower, the six
    /// manager/worker projection matrices, and the shared LM-head matrix as
    /// packed FP16 execution mirrors while retaining FP32 masters, gradients,
    /// optimizer moments, arithmetic, and accumulation.
    Fp16StorageFp32Compute,
    /// Parity-first mixed precision: keep the FP16 execution mirrors and run
    /// LM-head parameter-gradient products in native FP16, but keep the
    /// CE->LM upstream input adjoint plus the rest of the graph backward in
    /// FP32 arithmetic. This preserves the largest LM dW bandwidth win without
    /// exposing AdamW to sign flips from near-zero half-rounded upstream grads.
    Fp16StorageParity,
    /// Retain the same FP16 execution mirrors and FP32 masters/gradients/
    /// optimizer state, but execute the CE->LM linear backward boundary with
    /// native FP16 adjoints/products and FP32 accumulation. This is the first
    /// intentionally numerically distinct AMP-style training-compute arm.
    Fp16StorageFp16LmBackward,
}

impl HierarchosTrainingPrecisionPolicy {
    pub const fn label(self) -> &'static str {
        match self {
            Self::Fp32 => "fp32",
            Self::Fp16StorageFp32Compute => "fp16-storage-fp32-compute",
            Self::Fp16StorageParity => "fp16-storage-parity",
            Self::Fp16StorageFp16LmBackward => "fp16-storage-fp16-lm-backward",
        }
    }

    pub const fn uses_fp16_parameter_storage(self) -> bool {
        !matches!(self, Self::Fp32)
    }
}

