    #[allow(clippy::too_many_arguments)]
    fn train_raw_token_tape_sequences_budgeted_with_source_scale_and_readback_policy(
        &mut self,
        batch: usize,
        h_initial_packed_states: &[&[f32]],
        l_initial_packed_states: &[&[f32]],
        sequences: &[HierarchosRawTokenTapeMicrobatchInput<'_>],
        hyper: AdamWHyperParams,
        normalization: HierarchosSequenceGradientNormalization,
        accumulation_mode: HierarchosTokenTapeUpdateMode,
        policy: HierarchosTapeMemoryPolicy,
        loss_source_scale: f32,
        source_scaled_backward_domain: bool,
        backward_cap_objective: Option<HierarchosLabeledSequenceObjective>,
        readback_policy: HierarchosTokenTapeReadbackPolicy,
    ) -> Result<HierarchosBudgetedTokenTapeTrainResult> {
        let (requested_tokens_per_sequence, total_tokens) = Self::raw_token_tape_window_shape(
            h_initial_packed_states,
            l_initial_packed_states,
            sequences,
        )?;
        let baseline_plan = self.plan_token_tape_memory(
            batch,
            sequences.len(),
            requested_tokens_per_sequence,
            policy,
        )?;
        let plan = self.maybe_select_online_token_tape_exploration(
            batch,
            sequences.len(),
            requested_tokens_per_sequence,
            policy,
            baseline_plan,
        )?;
        if !plan.current_backend_executable {
            bail!("Vulkan raw-token tape planner returned a non-executable memory plan");
        }
        self.apply_token_tape_policy_arm(batch, &plan)?;
        self.train_raw_token_tape_sequences_with_resolved_plan(
            batch,
            h_initial_packed_states,
            l_initial_packed_states,
            sequences,
            hyper,
            normalization,
            requested_tokens_per_sequence,
            total_tokens,
            plan,
            accumulation_mode,
            loss_source_scale,
            source_scaled_backward_domain,
            backward_cap_objective,
            readback_policy,
        )
    }

    /// Execute one explicit, memory-validated raw-token training plan. The
