    fn raw_token_tape_window_shape(
        h_initial_packed_states: &[&[f32]],
        l_initial_packed_states: &[&[f32]],
        sequences: &[HierarchosRawTokenTapeMicrobatchInput<'_>],
    ) -> Result<(usize, usize)> {
        if sequences.is_empty() {
            bail!("budgeted raw-token tape training requires at least one sequence");
        }
        if h_initial_packed_states.len() != sequences.len()
            || l_initial_packed_states.len() != sequences.len()
        {
            bail!(
                "budgeted raw-token tape initial-state counts H={} L={} do not match {} sequences",
                h_initial_packed_states.len(),
                l_initial_packed_states.len(),
                sequences.len()
            );
        }
        let requested_tokens_per_sequence = sequences
            .iter()
            .map(|sequence| sequence.steps.len())
            .max()
            .context("budgeted raw-token tape training has no sequence lengths")?;
        if requested_tokens_per_sequence == 0 {
            bail!("budgeted raw-token tape training does not accept empty sequences");
        }
        let total_tokens = sequences.iter().try_fold(0usize, |total, sequence| {
            if sequence.steps.is_empty() {
                bail!("budgeted raw-token tape training does not accept empty sequences");
            }
            total
                .checked_add(sequence.steps.len())
                .context("budgeted raw-token tape total token count overflow")
        })?;
        Ok((requested_tokens_per_sequence, total_tokens))
    }

    #[allow(clippy::too_many_arguments)]
    fn train_raw_token_tape_sequences_with_resolved_plan(
        &mut self,
        batch: usize,
        h_initial_packed_states: &[&[f32]],
        l_initial_packed_states: &[&[f32]],
        sequences: &[HierarchosRawTokenTapeMicrobatchInput<'_>],
        hyper: AdamWHyperParams,
        normalization: HierarchosSequenceGradientNormalization,
        requested_tokens_per_sequence: usize,
        total_tokens: usize,
        plan: HierarchosTokenTapeMemoryPlan,
        accumulation_mode: HierarchosTokenTapeUpdateMode,
        loss_source_scale: f32,
        source_scaled_backward_domain: bool,
        backward_cap_objective: Option<HierarchosLabeledSequenceObjective>,
        readback_policy: HierarchosTokenTapeReadbackPolicy,
    ) -> Result<HierarchosBudgetedTokenTapeTrainResult> {
        if !plan.current_backend_executable {
            bail!("Vulkan raw-token tape planner returned a non-executable memory plan");
        }
        let window_supervision_mass =
            if normalization == HierarchosSequenceGradientNormalization::MeanBySupervisionWeight {
                Some(explicit_supervision_weight_mass(
                    batch,
                    sequences
                        .iter()
                        .flat_map(|sequence| sequence.steps.iter())
                        .map(|step| step.supervision_weights),
                )?)
            } else {
                None
            };
        let online_window = self.begin_online_token_tape_window(&plan);

        let chunk_size = plan.sequence_microbatch_size;
        let chunk_count = sequences.len().div_ceil(chunk_size);
        let mut all_results = Vec::with_capacity(sequences.len());
        let mut queue_submissions = 0u32;
        let mut last_optimizer = None;
        for chunk_index in 0..chunk_count {
            let start = chunk_index
                .checked_mul(chunk_size)
                .context("budgeted raw-token tape chunk offset overflow")?;
            let end = sequences.len().min(
                start
                    .checked_add(chunk_size)
                    .context("budgeted raw-token tape chunk end overflow")?,
            );
            let chunk_accumulation_mode =
                budgeted_chunk_update_mode(accumulation_mode, chunk_index, chunk_count);
            let result = if plan.state_checkpoint_stride == 1 {
                let mut arena = self.create_token_tape_arena(
                    batch,
                    requested_tokens_per_sequence,
                    &h_initial_packed_states[start..end],
                    &l_initial_packed_states[start..end],
                )?;
                self.train_raw_token_tape_microbatch_with_update_mode_and_readback_policy(
                    &mut arena,
                    &sequences[start..end],
                    hyper,
                    normalization,
                    chunk_accumulation_mode,
                    Some(total_tokens),
                    window_supervision_mass,
                    loss_source_scale,
                    source_scaled_backward_domain,
                    backward_cap_objective,
                    readback_policy,
                )?
            } else {
                let mut arena = self.create_sparse_token_tape_arena(
                    batch,
                    requested_tokens_per_sequence,
                    plan.state_checkpoint_stride,
                    &h_initial_packed_states[start..end],
                    &l_initial_packed_states[start..end],
                )?;
                self.train_raw_sparse_token_tape_microbatch_with_update_mode(
                    &mut arena,
                    &sequences[start..end],
                    hyper,
                    normalization,
                    chunk_accumulation_mode,
                    Some(total_tokens),
                    window_supervision_mass,
                    loss_source_scale,
                    source_scaled_backward_domain,
                    backward_cap_objective,
                    readback_policy,
                )?
            };
            queue_submissions = queue_submissions
                .checked_add(result.queue_submissions)
                .context("budgeted raw-token tape queue submission count overflow")?;
            last_optimizer = Some(result.full_model_optimizer);
            all_results.extend(result.sequences);
        }

        if let Some(window) = online_window {
            self.persist_online_token_tape_observation(
                batch,
                sequences.len(),
                requested_tokens_per_sequence,
                total_tokens,
                &plan,
                window,
            );
        }

        Ok(HierarchosBudgetedTokenTapeTrainResult {
            sequences: all_results,
            total_tokens,
            full_model_optimizer: last_optimizer
                .context("budgeted raw-token tape training produced no optimizer result")?,
            queue_submissions,
            plan,
        })
    }

    fn record_token_tape_result_readback(
        &self,
        commands: &mut vulkan::ComputeBatch,
        tape: &HierarchosTokenTape,
        steps: &[HierarchosTokenTapeStepInput<'_>],
    ) -> Result<HierarchosTokenTapeReadback> {
        let shadow_steps = steps
            .iter()
            .map(|step| step.shadow_steps)
            .collect::<Vec<_>>();
        self.record_token_tape_result_readback_with_shadow_steps(commands, tape, &shadow_steps)
    }

    fn record_token_tape_result_readback_with_shadow_steps(
        &self,
        commands: &mut vulkan::ComputeBatch,
        tape: &HierarchosTokenTape,
        shadow_steps: &[usize],
    ) -> Result<HierarchosTokenTapeReadback> {
        let mut selected_index_readbacks = Vec::with_capacity(shadow_steps.len());
        let mut executed_steps_readbacks = Vec::with_capacity(shadow_steps.len());
        let mut effective_l_steps_readbacks = Vec::with_capacity(shadow_steps.len());
        let mut active_history_readbacks = Vec::with_capacity(shadow_steps.len());
        for &step_count in shadow_steps {
            selected_index_readbacks.push(GpuBuffer::zeros_host_f32(&self.device, tape.batch)?);
            executed_steps_readbacks.push(GpuBuffer::zeros_host_f32(&self.device, tape.batch)?);
            effective_l_steps_readbacks.push(GpuBuffer::zeros_host_f32(&self.device, tape.batch)?);
            active_history_readbacks.push(
                (0..=step_count)
                    .map(|_| GpuBuffer::zeros_host_f32(&self.device, tape.batch))
                    .collect::<Result<Vec<_>>>()?,
            );
        }

        commands.readback_f32(
            &tape.h_states[shadow_steps.len()],
            &tape.h_final_state_readback,
            tape.h_state_len,
        )?;
        commands.readback_f32(
            &tape.l_states[shadow_steps.len()],
            &tape.l_final_state_readback,
            tape.l_state_len,
        )?;
        commands.readback_f32(
            &tape.h_adjoint,
            &tape.h_initial_adjoint_readback,
            tape.h_state_len,
        )?;
        commands.readback_f32(
            &tape.l_adjoint,
            &tape.l_initial_adjoint_readback,
            tape.l_state_len,
        )?;
        for token_index in 0..shadow_steps.len() {
            let control = &tape.controls[token_index];
            commands.readback_f32(
                &control.h_selected_index,
                &selected_index_readbacks[token_index],
                tape.batch,
            )?;
            commands.readback_f32(
                &control.h_executed_steps,
                &executed_steps_readbacks[token_index],
                tape.batch,
            )?;
            commands.readback_f32(
                &control.worker_effective_l_steps,
                &effective_l_steps_readbacks[token_index],
                tape.batch,
            )?;
            for (active, readback) in control
                .worker_active_history
                .iter()
                .zip(&active_history_readbacks[token_index])
                .take(shadow_steps[token_index] + 1)
            {
                commands.readback_f32(active, readback, tape.batch)?;
            }
        }
        Ok(HierarchosTokenTapeReadback {
            selected_index: selected_index_readbacks,
            executed_steps: executed_steps_readbacks,
            effective_l_steps: effective_l_steps_readbacks,
            active_history: active_history_readbacks,
        })
    }

    fn record_sparse_token_tape_result_readback(
        &self,
        commands: &mut vulkan::ComputeBatch,
        tape: &HierarchosSparseTokenTape,
        steps: &[HierarchosTokenTapeStepInput<'_>],
    ) -> Result<HierarchosTokenTapeReadback> {
        let shadow_steps = steps
            .iter()
            .map(|step| step.shadow_steps)
            .collect::<Vec<_>>();
        self.record_sparse_token_tape_result_readback_with_shadow_steps(
            commands,
            tape,
            &shadow_steps,
        )
    }

    fn record_sparse_token_tape_result_readback_with_shadow_steps(
        &self,
        commands: &mut vulkan::ComputeBatch,
        tape: &HierarchosSparseTokenTape,
        shadow_steps: &[usize],
    ) -> Result<HierarchosTokenTapeReadback> {
        let final_checkpoint_index = shadow_steps.len().div_ceil(tape.checkpoint_stride);
        let mut selected_index_readbacks = Vec::with_capacity(shadow_steps.len());
        let mut executed_steps_readbacks = Vec::with_capacity(shadow_steps.len());
        let mut effective_l_steps_readbacks = Vec::with_capacity(shadow_steps.len());
        let mut active_history_readbacks = Vec::with_capacity(shadow_steps.len());
        for &step_count in shadow_steps {
            selected_index_readbacks.push(GpuBuffer::zeros_host_f32(&self.device, tape.batch)?);
            executed_steps_readbacks.push(GpuBuffer::zeros_host_f32(&self.device, tape.batch)?);
            effective_l_steps_readbacks.push(GpuBuffer::zeros_host_f32(&self.device, tape.batch)?);
            active_history_readbacks.push(
                (0..=step_count)
                    .map(|_| GpuBuffer::zeros_host_f32(&self.device, tape.batch))
                    .collect::<Result<Vec<_>>>()?,
            );
        }

        commands.readback_f32(
            &tape.h_checkpoints[final_checkpoint_index],
            &tape.h_final_state_readback,
            tape.h_state_len,
        )?;
        commands.readback_f32(
            &tape.l_checkpoints[final_checkpoint_index],
            &tape.l_final_state_readback,
            tape.l_state_len,
        )?;
        commands.readback_f32(
            &tape.h_adjoint,
            &tape.h_initial_adjoint_readback,
            tape.h_state_len,
        )?;
        commands.readback_f32(
            &tape.l_adjoint,
            &tape.l_initial_adjoint_readback,
            tape.l_state_len,
        )?;
        for token_index in 0..shadow_steps.len() {
            let control = &tape.controls[token_index];
            commands.readback_f32(
                &control.h_selected_index,
                &selected_index_readbacks[token_index],
                tape.batch,
            )?;
            commands.readback_f32(
                &control.h_executed_steps,
                &executed_steps_readbacks[token_index],
                tape.batch,
            )?;
            commands.readback_f32(
                &control.worker_effective_l_steps,
                &effective_l_steps_readbacks[token_index],
                tape.batch,
            )?;
            for (active, readback) in control
                .worker_active_history
                .iter()
                .zip(&active_history_readbacks[token_index])
                .take(shadow_steps[token_index] + 1)
            {
                commands.readback_f32(active, readback, tape.batch)?;
            }
        }
        Ok(HierarchosTokenTapeReadback {
            selected_index: selected_index_readbacks,
            executed_steps: executed_steps_readbacks,
            effective_l_steps: effective_l_steps_readbacks,
            active_history: active_history_readbacks,
        })
    }

    fn finalize_token_tape_result_readback(
        &self,
        batch: usize,
        steps: &[HierarchosTokenTapeStepInput<'_>],
        readback: HierarchosTokenTapeReadback,
    ) -> Result<Vec<HierarchosTokenTapeControlSnapshot>> {
        self.finalize_token_tape_result_readback_with_count(batch, steps.len(), readback)
    }

    fn finalize_token_tape_result_readback_with_count(
        &self,
        batch: usize,
        token_count: usize,
        readback: HierarchosTokenTapeReadback,
    ) -> Result<Vec<HierarchosTokenTapeControlSnapshot>> {
        let mut controls = Vec::with_capacity(token_count);
        for token_index in 0..token_count {
            let manager_selected_index = readback.selected_index[token_index]
                .read_f32(batch)?
                .into_iter()
                .map(|value| value as u32)
                .collect();
            let manager_executed_steps = readback.executed_steps[token_index].read_f32(batch)?;
            let worker_effective_l_steps =
                readback.effective_l_steps[token_index].read_f32(batch)?;
            let worker_active_history = readback.active_history[token_index]
                .iter()
                .map(|slot| slot.read_f32(batch))
                .collect::<Result<Vec<_>>>()?;
            controls.push(HierarchosTokenTapeControlSnapshot {
                manager_selected_index,
                manager_executed_steps,
                worker_effective_l_steps,
                worker_active_history,
            });
        }
        Ok(controls)
    }

    /// Seed the reverse boundary for the current rolling state. This remains a
    /// host-facing diagnostic/bootstrap seam; the multi-token tape will replace
    /// it by copying the next token's state adjoints device-to-device.
    pub fn set_sequence_state_adjoints(
        &self,
        arena: &HierarchosSequenceStateArena,
        h_packed_state_adjoint: &[f32],
        l_packed_state_adjoint: &[f32],
    ) -> Result<()> {
        validate_f32_input(
            "sequence-state h_packed_state_adjoint",
            h_packed_state_adjoint,
            arena.h_state_len,
        )?;
        validate_f32_input(
            "sequence-state l_packed_state_adjoint",
            l_packed_state_adjoint,
            arena.l_state_len,
        )?;
        let mut commands = vulkan::ComputeBatch::new_with_persistent_upload_arena(
            &self.device,
            Arc::clone(&arena.upload_arena),
        )?;
        commands.upload_f32(&arena.h_state_adjoint, h_packed_state_adjoint)?;
        commands.upload_f32(&arena.l_state_adjoint, l_packed_state_adjoint)?;
        commands.submit()
    }

    /// Capture the committed state and initial-state adjoints left by the most
    /// recent full worker/loss token. H commits the hard-ACT selected state; L
    /// commits the real post-refinement transition. All four copies remain on
    /// device and therefore form a stable handoff to an outer sequence tape.
    pub fn capture_last_worker_step_into_sequence_state(
        &self,
        arena: &HierarchosSequenceStateArena,
    ) -> Result<()> {
        let expected_h_state_len = arena
            .batch
            .checked_mul(self.config.h_hidden)
            .and_then(|value| value.checked_mul(self.h_recurrent.state_size()))
            .context("sequence-state H capture length overflow")?;
        let expected_l_state_len = arena
            .batch
            .checked_mul(self.config.l_hidden)
            .and_then(|value| value.checked_mul(self.l_recurrent.state_size()))
            .context("sequence-state L capture length overflow")?;
        if arena.h_state_len != expected_h_state_len || arena.l_state_len != expected_l_state_len {
            bail!("sequence-state arena shape does not match this training graph");
        }

        let mut commands = vulkan::ComputeBatch::new_with_persistent_upload_arena(
            &self.device,
            Arc::clone(&arena.upload_arena),
        )?;
        commands.copy_f32(&self.h_selected_state, &arena.h_state, arena.h_state_len)?;
        commands.copy_f32(
            self.l_recurrent.graph_state_step_buffer(1)?,
            &arena.l_state,
            arena.l_state_len,
        )?;
        commands.copy_f32(
            self.h_recurrent.graph_state_grad_carry_buffer(),
            &arena.h_state_adjoint,
            arena.h_state_len,
        )?;
        commands.copy_f32(
            self.l_recurrent.graph_state_grad_carry_buffer(),
            &arena.l_state_adjoint,
            arena.l_state_len,
        )?;
        commands.submit()
    }

    /// Read back a sequence boundary for parity/debugging. Production sequence
    /// scheduling should consume the arena buffers directly and avoid this host
    /// synchronization.
    pub fn sequence_state_snapshot(
        &self,
        arena: &HierarchosSequenceStateArena,
    ) -> Result<HierarchosSequenceStateSnapshot> {
        let mut commands = vulkan::ComputeBatch::new_with_persistent_upload_arena(
            &self.device,
            Arc::clone(&arena.upload_arena),
        )?;
        commands.readback_f32(&arena.h_state, &arena.h_state_readback, arena.h_state_len)?;
        commands.readback_f32(&arena.l_state, &arena.l_state_readback, arena.l_state_len)?;
        commands.readback_f32(
            &arena.h_state_adjoint,
            &arena.h_state_adjoint_readback,
            arena.h_state_len,
        )?;
        commands.readback_f32(
            &arena.l_state_adjoint,
            &arena.l_state_adjoint_readback,
            arena.l_state_len,
        )?;
        commands.submit()?;
        Ok(HierarchosSequenceStateSnapshot {
            batch: arena.batch,
            h_packed_state: arena.h_state_readback.read_f32(arena.h_state_len)?,
            l_packed_state: arena.l_state_readback.read_f32(arena.l_state_len)?,
            h_packed_state_adjoint: arena.h_state_adjoint_readback.read_f32(arena.h_state_len)?,
            l_packed_state_adjoint: arena.l_state_adjoint_readback.read_f32(arena.l_state_len)?,
        })
    }

    /// Snapshot the output LayerNorm affine parameters. This is primarily a
    /// parity/checkpoint seam while the full-model optimizer state is being
    /// consolidated.
    pub fn out_norm_parameters(&self) -> Result<(Vec<f32>, Vec<f32>)> {
        Ok((self.output.norm_weights()?, self.output.norm_bias()?))
    }

    /// Snapshot the ten-tensor manager/worker AdamW registry. This is the first
    /// checkpointable piece of the future full-model registry; the same state
    /// object is serialized as ordinary FP32 SafeTensors moment arrays.
    pub fn projection_optimizer_state(&self) -> Result<AdamWOptimizerState> {
        self.projections.optimizer_state()
    }

    pub fn save_projection_optimizer_checkpoint(&self, path: impl AsRef<Path>) -> Result<()> {
        let state = self.projection_optimizer_state()?;
        write_adamw_optimizer_state(path.as_ref(), &state)
    }

    pub fn load_projection_optimizer_checkpoint(&mut self, path: impl AsRef<Path>) -> Result<()> {
        let state = read_adamw_optimizer_state(path.as_ref())?;
        self.projections.load_optimizer_state(&state)
    }

    /// Snapshot the canonical H/L/projection/out_norm/tied-LM AdamW registry.
    /// Slot names are the exact model-package tensor names, making this state
    /// directly resumable alongside the ordinary PyTorch-layout SafeTensors.
    pub fn full_model_optimizer_state(&self) -> Result<AdamWOptimizerState> {
        self.full_model_optimizer.state_snapshot()
    }

    /// Read the canonical in-flight gradient registry at a microbatch boundary.
    /// The tied LM-head entry is sourced from whichever physical topology owns
    /// it for the current window, while the returned names remain portable.
    pub fn full_model_pending_gradient_snapshots(&self) -> Result<Vec<RwkvParameterSnapshot>> {
        if !self.full_model_accumulation_open {
            bail!("pending full-model gradients require an open accumulation window");
        }
        let direct_lm_gradient = self
            .full_model_direct_lm_gradient
            .context("open accumulation window is missing lm_head gradient topology")?;
        let override_gradient = direct_lm_gradient.then_some((
            LM_HEAD_WEIGHT_TENSOR_NAME,
            self.shared_lm_head.gradient_buffer(),
        ));
        self.full_model_optimizer
            .gradient_state_snapshot_with_override(override_gradient)
    }

    fn full_model_pending_gradient_metadata(&self) -> Result<PendingGradientShardMetadata> {
        if !self.full_model_accumulation_open {
            bail!("pending full-model gradient shard requires an open accumulation window");
        }
        let accumulation = self.full_model_accumulation_normalization.context(
            "distributed pending-gradient export requires sequence normalization metadata",
        )?;
        if accumulation.consumed_token_count == 0 {
            bail!("distributed pending-gradient shard has zero consumed tokens");
        }
        let target_token_count = accumulation
            .target_token_count
            .unwrap_or(accumulation.consumed_token_count);
        if target_token_count < accumulation.consumed_token_count {
            bail!(
                "distributed pending-gradient target token count {target_token_count} is smaller than consumed count {}",
                accumulation.consumed_token_count
            );
        }
        let target_supervision_mass = if accumulation.normalization
            == HierarchosSequenceGradientNormalization::MeanBySupervisionWeight
        {
            let mass = accumulation
                .target_supervision_mass
                .or(accumulation.consumed_supervision_mass)
                .context("weighted distributed gradient shard has no supervision mass")?;
            if !mass.is_finite() || mass <= 0.0 {
                bail!(
                    "weighted distributed gradient shard supervision mass must be finite and positive; got {mass}"
                );
            }
            Some(mass)
        } else {
            None
        };
        let ltm_alignment_cost_total = if self.ltm_alignment_controller.enabled() {
            let reducer = self
                .ltm_alignment_cost_sum_reducer
                .as_ref()
                .context("distributed LTM alignment cost reducer is unavailable")?;
            let mut commands = vulkan::ComputeBatch::new(&self.device)?;
            reducer.record_sum(
                &mut commands,
                &self.ltm_alignment_cost_accum,
                self.ltm_alignment_cost_accum.f32_capacity(),
            )?;
            commands.submit()?;
            let total = reducer.read_sum()?;
            if !total.is_finite() || total < 0.0 {
                bail!(
                    "distributed LTM alignment cost total must be finite and non-negative; got {total}"
                );
            }
            total
        } else {
            0.0
        };
        Ok(PendingGradientShardMetadata {
            architecture_revision: self.config.architecture_revision.clone(),
            training_precision_policy: self.training_precision_policy.label().to_string(),
            optimizer_step: self.full_model_optimizer.current_step(),
            optimizer_tensor_count: self.full_model_optimizer.tensor_count(),
            training_step: self.training_step(),
            normalization: accumulation.normalization,
            consumed_token_count: accumulation.consumed_token_count,
            consumed_supervision_mass: accumulation.consumed_supervision_mass,
            target_token_count,
            target_supervision_mass,
            val_proj_active_in_window: self.val_proj_active_in_window,
            ltm_alignment_pytorch_tbptt_weighting_in_window: self
                .ltm_alignment_pytorch_tbptt_weighting_in_window,
            ltm_alignment_controller: self.ltm_alignment_controller.clone(),
            ltm_alignment_cost_total,
        })
    }

    /// Export one replica's open full-model gradient window in canonical model
    /// tensor layout. This compatibility/checkpoint seam materializes the whole
    /// tensor payload; live multi-adapter training should prefer
    /// `accumulate_full_model_pending_gradients_streamed_from` to bound host
    /// gradient memory independently of model size.
    pub fn full_model_pending_gradient_shard(&self) -> Result<HierarchosPendingGradientShard> {
        let metadata = self.full_model_pending_gradient_metadata()?;
        Ok(HierarchosPendingGradientShard {
            architecture_revision: metadata.architecture_revision,
            training_precision_policy: metadata.training_precision_policy,
            optimizer_step: metadata.optimizer_step,
            optimizer_tensor_count: metadata.optimizer_tensor_count,
            training_step: metadata.training_step,
            gradients: self.full_model_pending_gradient_snapshots()?,
            normalization: metadata.normalization,
            consumed_token_count: metadata.consumed_token_count,
            consumed_supervision_mass: metadata.consumed_supervision_mass,
            target_token_count: metadata.target_token_count,
            target_supervision_mass: metadata.target_supervision_mass,
            val_proj_active_in_window: metadata.val_proj_active_in_window,
            ltm_alignment_pytorch_tbptt_weighting_in_window: metadata
                .ltm_alignment_pytorch_tbptt_weighting_in_window,
            ltm_alignment_controller: metadata.ltm_alignment_controller,
            ltm_alignment_cost_total: metadata.ltm_alignment_cost_total,
        })
    }

    /// Reduce a remote replica's canonical pending-gradient shard into this
    /// graph. Host memory is currently the cross-device transport, but every
    /// gradient tensor addition is recorded as Vulkan compute on the
    /// destination adapter.
    ///
    /// Shards must be imported in logical PyTorch microbatch order. Gradient
    /// tensors and window-wide sampled-row counts are commutative, but the exact
    /// TBPTT writer-readiness controller is deliberately not: PyTorch resets its
    /// controller observation for each logical microbatch and only the
    /// optimizer-closing microbatch survives. Accordingly, an exact-TBPTT shard
    /// imported here replaces the destination controller-microbatch row count
    /// and controller cost while still summing the full gradient window. The
    /// last imported shard therefore becomes the controller-closing microbatch.
    pub fn accumulate_full_model_pending_gradient_shard(
        &mut self,
        shard: &HierarchosPendingGradientShard,
    ) -> Result<()> {
        if !self.full_model_accumulation_open {
            bail!("distributed pending-gradient import requires an open destination window");
        }
        if shard.architecture_revision != self.config.architecture_revision {
            bail!(
                "distributed gradient shard architecture {:?} does not match destination {:?}",
                shard.architecture_revision,
                self.config.architecture_revision
            );
        }
        if shard.training_precision_policy != self.training_precision_policy.label() {
            bail!(
                "distributed gradient shard precision {:?} does not match destination {:?}",
                shard.training_precision_policy,
                self.training_precision_policy.label()
            );
        }
        if shard.optimizer_step != self.full_model_optimizer.current_step()
            || shard.optimizer_tensor_count != self.full_model_optimizer.tensor_count()
        {
            bail!(
                "distributed gradient shard optimizer step/tensors={}/{} does not match destination {}/{}",
                shard.optimizer_step,
                shard.optimizer_tensor_count,
                self.full_model_optimizer.current_step(),
                self.full_model_optimizer.tensor_count()
            );
        }
        if shard.training_step != self.training_step() {
            bail!(
                "distributed gradient shard training step {:?} does not match destination {:?}",
                shard.training_step,
                self.training_step()
            );
        }
        if shard.consumed_token_count == 0 || shard.target_token_count < shard.consumed_token_count
        {
            bail!(
                "distributed gradient shard token geometry consumed={} target={} is invalid",
                shard.consumed_token_count,
                shard.target_token_count
            );
        }
        let mut local_controller_identity = self.ltm_alignment_controller.clone();
        let mut remote_controller_identity = shard.ltm_alignment_controller.clone();
        local_controller_identity.sampled_rows_in_window = 0;
        local_controller_identity.sampled_rows_in_controller_microbatch = 0;
        remote_controller_identity.sampled_rows_in_window = 0;
        remote_controller_identity.sampled_rows_in_controller_microbatch = 0;
        if local_controller_identity != remote_controller_identity {
            bail!(
                "distributed gradient shard LTM controller base state does not match destination"
            );
        }
        if shard.ltm_alignment_pytorch_tbptt_weighting_in_window
            != self.ltm_alignment_pytorch_tbptt_weighting_in_window
        {
            bail!(
                "distributed gradient shard LTM weighting mode {:?} does not match destination {:?}",
                shard.ltm_alignment_pytorch_tbptt_weighting_in_window,
                self.ltm_alignment_pytorch_tbptt_weighting_in_window
            );
        }
        if !shard.ltm_alignment_cost_total.is_finite() || shard.ltm_alignment_cost_total < 0.0 {
            bail!(
                "distributed gradient shard LTM cost must be finite and non-negative; got {}",
                shard.ltm_alignment_cost_total
            );
        }

        let current = self.full_model_accumulation_normalization.context(
            "open distributed destination window is missing sequence normalization metadata",
        )?;
        if shard.normalization != current.normalization {
            bail!(
                "distributed gradient normalization changed from {} to {}",
                current.normalization.checkpoint_label(),
                shard.normalization.checkpoint_label()
            );
        }
        let merged_consumed_token_count = current
            .consumed_token_count
            .checked_add(shard.consumed_token_count)
            .context("distributed accumulation consumed-token count overflow")?;
        let local_target_token_count = current
            .target_token_count
            .unwrap_or(current.consumed_token_count);
        let merged_target_token_count = local_target_token_count
            .checked_add(shard.target_token_count)
            .context("distributed accumulation target-token count overflow")?;
        if merged_target_token_count < merged_consumed_token_count {
            bail!(
                "distributed accumulation merged target token count {merged_target_token_count} is smaller than consumed count {merged_consumed_token_count}"
            );
        }
        let (merged_consumed_supervision_mass, merged_target_supervision_mass) = if current
            .normalization
            == HierarchosSequenceGradientNormalization::MeanBySupervisionWeight
        {
            let local_consumed = current
                .consumed_supervision_mass
                .context("weighted distributed destination lost consumed supervision mass")?;
            let remote_consumed = shard
                .consumed_supervision_mass
                .context("weighted distributed shard has no consumed supervision mass")?;
            let local_target = current
                .target_supervision_mass
                .or(current.consumed_supervision_mass)
                .context("weighted distributed destination has no target supervision mass")?;
            let remote_target = shard
                .target_supervision_mass
                .context("weighted distributed shard has no target supervision mass")?;
            for (name, value) in [
                ("local consumed", local_consumed),
                ("remote consumed", remote_consumed),
                ("local target", local_target),
                ("remote target", remote_target),
            ] {
                if !value.is_finite() || value <= 0.0 {
                    bail!(
                            "weighted distributed {name} supervision mass must be finite and positive; got {value}"
                        );
                }
            }
            let consumed = local_consumed + remote_consumed;
            let target = local_target + remote_target;
            if !consumed.is_finite() || !target.is_finite() {
                bail!("weighted distributed supervision-mass reduction overflowed");
            }
            let tolerance = 8.0 * f32::EPSILON * target.abs().max(consumed.abs()).max(1.0);
            if target + tolerance < consumed {
                bail!(
                        "weighted distributed target supervision mass {target} is smaller than consumed mass {consumed}"
                    );
            }
            (Some(consumed), Some(target))
        } else {
            if shard.consumed_supervision_mass.is_some() || shard.target_supervision_mass.is_some()
            {
                bail!(
                    "non-weighted distributed gradient shard unexpectedly carries supervision mass"
                );
            }
            (None, None)
        };
        let merged_sampled_rows = self
            .ltm_alignment_controller
            .sampled_rows_in_window
            .checked_add(shard.ltm_alignment_controller.sampled_rows_in_window)
            .context("distributed LTM sampled-row counter overflow")?;
        let exact_pytorch_tbptt =
            self.ltm_alignment_pytorch_tbptt_weighting_in_window == Some(true);
        let merged_controller_rows = if exact_pytorch_tbptt {
            shard
                .ltm_alignment_controller
                .sampled_rows_in_controller_microbatch
        } else {
            self.ltm_alignment_controller
                .sampled_rows_in_controller_microbatch
                .checked_add(
                    shard
                        .ltm_alignment_controller
                        .sampled_rows_in_controller_microbatch,
                )
                .context("distributed LTM controller sampled-row counter overflow")?
        };
        if shard.val_proj_active_in_window
            != (shard.ltm_alignment_controller.sampled_rows_in_window != 0)
            && shard.ltm_alignment_controller.enabled()
        {
            bail!("distributed gradient shard has inconsistent val_proj/LTM sampled-row state");
        }

        let direct_lm_gradient = self
            .full_model_direct_lm_gradient
            .context("open distributed destination window is missing lm_head gradient topology")?;
        let lm_gradient_override =
            direct_lm_gradient.then(|| self.shared_lm_head.gradient_buffer().clone());
        let override_gradient = lm_gradient_override
            .as_ref()
            .map(|gradient| (LM_HEAD_WEIGHT_TENSOR_NAME, gradient));
        let mut commands = vulkan::ComputeBatch::new(&self.device)?;
        let uploaded_gradients = self
            .full_model_optimizer
            .record_accumulate_gradient_state_with_override(
                &mut commands,
                &shard.gradients,
                override_gradient,
            )?;
        let ltm_cost_upload = if exact_pytorch_tbptt {
            // Exact TBPTT resets this observation at every logical microbatch.
            // Import order is therefore semantically significant even though
            // the gradient reduction itself is commutative: the latest shard
            // replaces the controller observation on the destination.
            commands.fill_zero_f32(
                &self.ltm_alignment_cost_accum,
                self.ltm_alignment_cost_accum.f32_capacity(),
            )?;
            if shard.ltm_alignment_cost_total != 0.0 {
                commands.update_f32_at(
                    &self.ltm_alignment_cost_accum,
                    0,
                    shard.ltm_alignment_cost_total,
                )?;
            }
            None
        } else if shard.ltm_alignment_cost_total != 0.0 {
            let len = self.ltm_alignment_cost_accum.f32_capacity();
            let upload = GpuBuffer::transient_f32(&self.device, len)?;
            commands.fill_zero_f32(&upload, len)?;
            commands.update_f32_at(&upload, 0, shard.ltm_alignment_cost_total)?;
            self.record_worker_vector_accumulate(
                &mut commands,
                &self.ltm_alignment_cost_accum,
                &upload,
                len,
            )?;
            Some(upload)
        } else {
            None
        };
        commands.submit()?;
        drop(ltm_cost_upload);
        drop(uploaded_gradients);

        self.full_model_accumulation_normalization =
            Some(FullModelAccumulationNormalizationState {
                normalization: current.normalization,
                consumed_token_count: merged_consumed_token_count,
                consumed_supervision_mass: merged_consumed_supervision_mass,
                target_token_count: Some(merged_target_token_count),
                target_supervision_mass: merged_target_supervision_mass,
            });
        self.ltm_alignment_controller.sampled_rows_in_window = merged_sampled_rows;
        self.ltm_alignment_controller
            .sampled_rows_in_controller_microbatch = merged_controller_rows;
        self.val_proj_active_in_window |= shard.val_proj_active_in_window;
        Ok(())
    }

    fn plan_pending_gradient_merge(
        &self,
        shard: &PendingGradientShardMetadata,
    ) -> Result<PendingGradientMergePlan> {
        if !self.full_model_accumulation_open {
            bail!("distributed pending-gradient import requires an open destination window");
        }
        if shard.architecture_revision != self.config.architecture_revision {
            bail!(
                "distributed gradient shard architecture {:?} does not match destination {:?}",
                shard.architecture_revision,
                self.config.architecture_revision
            );
        }
        if shard.training_precision_policy != self.training_precision_policy.label() {
            bail!(
                "distributed gradient shard precision {:?} does not match destination {:?}",
                shard.training_precision_policy,
                self.training_precision_policy.label()
            );
        }
        if shard.optimizer_step != self.full_model_optimizer.current_step()
            || shard.optimizer_tensor_count != self.full_model_optimizer.tensor_count()
        {
            bail!(
                "distributed gradient shard optimizer step/tensors={}/{} does not match destination {}/{}",
                shard.optimizer_step,
                shard.optimizer_tensor_count,
                self.full_model_optimizer.current_step(),
                self.full_model_optimizer.tensor_count()
            );
        }
        if shard.training_step != self.training_step() {
            bail!(
                "distributed gradient shard training step {:?} does not match destination {:?}",
                shard.training_step,
                self.training_step()
            );
        }
        if shard.consumed_token_count == 0 || shard.target_token_count < shard.consumed_token_count
        {
            bail!(
                "distributed gradient shard token geometry consumed={} target={} is invalid",
                shard.consumed_token_count,
                shard.target_token_count
            );
        }

        let mut local_controller_identity = self.ltm_alignment_controller.clone();
        let mut remote_controller_identity = shard.ltm_alignment_controller.clone();
        local_controller_identity.sampled_rows_in_window = 0;
        local_controller_identity.sampled_rows_in_controller_microbatch = 0;
        remote_controller_identity.sampled_rows_in_window = 0;
        remote_controller_identity.sampled_rows_in_controller_microbatch = 0;
        if local_controller_identity != remote_controller_identity {
            bail!(
                "distributed gradient shard LTM controller base state does not match destination"
            );
        }
        if shard.ltm_alignment_pytorch_tbptt_weighting_in_window
            != self.ltm_alignment_pytorch_tbptt_weighting_in_window
        {
            bail!(
                "distributed gradient shard LTM weighting mode {:?} does not match destination {:?}",
                shard.ltm_alignment_pytorch_tbptt_weighting_in_window,
                self.ltm_alignment_pytorch_tbptt_weighting_in_window
            );
        }
        if !shard.ltm_alignment_cost_total.is_finite() || shard.ltm_alignment_cost_total < 0.0 {
            bail!(
                "distributed gradient shard LTM cost must be finite and non-negative; got {}",
                shard.ltm_alignment_cost_total
            );
        }

        let current = self.full_model_accumulation_normalization.context(
            "open distributed destination window is missing sequence normalization metadata",
        )?;
        if shard.normalization != current.normalization {
            bail!(
                "distributed gradient normalization changed from {} to {}",
                current.normalization.checkpoint_label(),
                shard.normalization.checkpoint_label()
            );
        }
        let merged_consumed_token_count = current
            .consumed_token_count
            .checked_add(shard.consumed_token_count)
            .context("distributed accumulation consumed-token count overflow")?;
        let local_target_token_count = current
            .target_token_count
            .unwrap_or(current.consumed_token_count);
        let merged_target_token_count = local_target_token_count
            .checked_add(shard.target_token_count)
            .context("distributed accumulation target-token count overflow")?;
        if merged_target_token_count < merged_consumed_token_count {
            bail!(
                "distributed accumulation merged target token count {merged_target_token_count} is smaller than consumed count {merged_consumed_token_count}"
            );
        }
        let (merged_consumed_supervision_mass, merged_target_supervision_mass) = if current
            .normalization
            == HierarchosSequenceGradientNormalization::MeanBySupervisionWeight
        {
            let local_consumed = current
                .consumed_supervision_mass
                .context("weighted distributed destination lost consumed supervision mass")?;
            let remote_consumed = shard
                .consumed_supervision_mass
                .context("weighted distributed shard has no consumed supervision mass")?;
            let local_target = current
                .target_supervision_mass
                .or(current.consumed_supervision_mass)
                .context("weighted distributed destination has no target supervision mass")?;
            let remote_target = shard
                .target_supervision_mass
                .context("weighted distributed shard has no target supervision mass")?;
            for (name, value) in [
                ("local consumed", local_consumed),
                ("remote consumed", remote_consumed),
                ("local target", local_target),
                ("remote target", remote_target),
            ] {
                if !value.is_finite() || value <= 0.0 {
                    bail!(
                        "weighted distributed {name} supervision mass must be finite and positive; got {value}"
                    );
                }
            }
            let consumed = local_consumed + remote_consumed;
            let target = local_target + remote_target;
            if !consumed.is_finite() || !target.is_finite() {
                bail!("weighted distributed supervision-mass reduction overflowed");
            }
            let tolerance = 8.0 * f32::EPSILON * target.abs().max(consumed.abs()).max(1.0);
            if target + tolerance < consumed {
                bail!(
                    "weighted distributed target supervision mass {target} is smaller than consumed mass {consumed}"
                );
            }
            (Some(consumed), Some(target))
        } else {
            if shard.consumed_supervision_mass.is_some() || shard.target_supervision_mass.is_some()
            {
                bail!(
                    "non-weighted distributed gradient shard unexpectedly carries supervision mass"
                );
            }
            (None, None)
        };
        let merged_sampled_rows = self
            .ltm_alignment_controller
            .sampled_rows_in_window
            .checked_add(shard.ltm_alignment_controller.sampled_rows_in_window)
            .context("distributed LTM sampled-row counter overflow")?;
        let exact_pytorch_tbptt =
            self.ltm_alignment_pytorch_tbptt_weighting_in_window == Some(true);
        let merged_controller_rows = if exact_pytorch_tbptt {
            shard
                .ltm_alignment_controller
                .sampled_rows_in_controller_microbatch
        } else {
            self.ltm_alignment_controller
                .sampled_rows_in_controller_microbatch
                .checked_add(
                    shard
                        .ltm_alignment_controller
                        .sampled_rows_in_controller_microbatch,
                )
                .context("distributed LTM controller sampled-row counter overflow")?
        };
        if shard.val_proj_active_in_window
            != (shard.ltm_alignment_controller.sampled_rows_in_window != 0)
            && shard.ltm_alignment_controller.enabled()
        {
            bail!("distributed gradient shard has inconsistent val_proj/LTM sampled-row state");
        }

        Ok(PendingGradientMergePlan {
            accumulation: FullModelAccumulationNormalizationState {
                normalization: current.normalization,
                consumed_token_count: merged_consumed_token_count,
                consumed_supervision_mass: merged_consumed_supervision_mass,
                target_token_count: Some(merged_target_token_count),
                target_supervision_mass: merged_target_supervision_mass,
            },
            sampled_rows_in_window: merged_sampled_rows,
            sampled_rows_in_controller_microbatch: merged_controller_rows,
            val_proj_active_in_window: self.val_proj_active_in_window
                || shard.val_proj_active_in_window,
            exact_pytorch_tbptt,
            ltm_alignment_cost_total: shard.ltm_alignment_cost_total,
        })
    }

    fn record_pending_gradient_merge_metadata(
        &self,
        commands: &mut vulkan::ComputeBatch,
        plan: &PendingGradientMergePlan,
    ) -> Result<Option<GpuBuffer>> {
        if plan.exact_pytorch_tbptt {
            commands.fill_zero_f32(
                &self.ltm_alignment_cost_accum,
                self.ltm_alignment_cost_accum.f32_capacity(),
            )?;
            if plan.ltm_alignment_cost_total != 0.0 {
                commands.update_f32_at(
                    &self.ltm_alignment_cost_accum,
                    0,
                    plan.ltm_alignment_cost_total,
                )?;
            }
            Ok(None)
        } else if plan.ltm_alignment_cost_total != 0.0 {
            let len = self.ltm_alignment_cost_accum.f32_capacity();
            let upload = GpuBuffer::transient_f32(&self.device, len)?;
            commands.fill_zero_f32(&upload, len)?;
            commands.update_f32_at(&upload, 0, plan.ltm_alignment_cost_total)?;
            self.record_worker_vector_accumulate(
                commands,
                &self.ltm_alignment_cost_accum,
                &upload,
                len,
            )?;
            Ok(Some(upload))
        } else {
            Ok(None)
        }
    }

    fn commit_pending_gradient_merge(&mut self, plan: PendingGradientMergePlan) {
        self.full_model_accumulation_normalization = Some(plan.accumulation);
        self.ltm_alignment_controller.sampled_rows_in_window = plan.sampled_rows_in_window;
        self.ltm_alignment_controller
            .sampled_rows_in_controller_microbatch = plan.sampled_rows_in_controller_microbatch;
        self.val_proj_active_in_window = plan.val_proj_active_in_window;
    }

    fn flush_pending_gradient_transport_slot(
        &self,
        slot: &mut PendingGradientTransportSlot,
        destination_override: Option<(&str, &GpuBuffer)>,
    ) -> Result<Option<usize>> {
        let Some(pending) = slot.pending else {
            return Ok(None);
        };
        let source_submission = slot
            .source_submission
            .take()
            .context("streamed gradient pipeline lost its source submission")?;
        source_submission.wait()?;

        // This slot's prior destination command may still be reducing the chunk
        // from two iterations ago. The current source readback has already run
        // concurrently with that work; only the host-visible destination window
        // and its device-local scratch must be retired before reuse.
        slot.wait_destination()?;
        slot.source_readback
            .copy_host_visible_f32_to(&slot.destination_staging, pending.len)?;

        let mut commands = vulkan::ComputeBatch::new(&self.device)?;
        commands.copy_f32_range(
            &slot.destination_staging,
            0,
            &slot.destination_upload,
            0,
            pending.len,
        )?;
        self.full_model_optimizer
            .record_accumulate_gradient_range_with_override(
                &mut commands,
                pending.tensor_index,
                pending.offset,
                &slot.destination_upload,
                &slot.destination_scratch,
                pending.len,
                destination_override,
            )?;
        slot.destination_submission = Some(commands.submit_async()?);
        slot.pending = None;
        Ok(Some(pending.len))
    }

    fn take_opaque_external_gradient_transport(
        &mut self,
        source_device: &VulkanDevice,
        chunk_capacity: usize,
    ) -> Result<(OpaqueExternalGradientTransport, bool)> {
        if let Some(index) = self
            .opaque_external_gradient_transports
            .iter()
            .position(|transport| transport.matches_devices(source_device, &self.device))
        {
            let existing = self.opaque_external_gradient_transports.swap_remove(index);
            if !existing.is_idle() {
                bail!(
                    "persistent opaque external gradient transport was checked out with in-flight work"
                );
            }
            if existing.chunk_capacity >= chunk_capacity {
                return Ok((existing, true));
            }

            match OpaqueExternalGradientTransport::new(
                source_device,
                &self.device,
                chunk_capacity,
                &self.optimizer_transport_scratch_slots,
            ) {
                Ok(upgraded) => return Ok((upgraded, false)),
                Err(err) => {
                    self.opaque_external_gradient_transports.push(existing);
                    return Err(err.context(
                        "growing persistent opaque external gradient transport capacity",
                    ));
                }
            }
        }

        Ok((
            OpaqueExternalGradientTransport::new(
                source_device,
                &self.device,
                chunk_capacity,
                &self.optimizer_transport_scratch_slots,
            )?,
            false,
        ))
    }

    /// Stream a replica's open canonical gradient registry into this graph with
    /// bounded host memory. Two reusable slots pipeline the path: while the
    /// replica queue reads back chunk N+1, the primary queue can copy and reduce
    /// chunk N. Each active range crosses adapters only through bounded
    /// host-visible Vulkan allocations, never a heap `Vec<f32>` or full-model
    /// gradient snapshot; all gradient arithmetic remains Vulkan compute.
    ///
    /// This is deliberately an in-process transport seam: `replica` may be on
    /// another Vulkan physical device selected through `VulkanDevice`. Device
    /// groups use direct peer memory, while compatible independent logical
    /// devices use a persistent two-slot opaque external-memory/semaphore path.
    /// Other pairs retain the bounded host-visible fallback while preserving the
    /// same canonical tensor and metadata validation contract.
    /// If a Vulkan error occurs after any destination chunk was committed, the
    /// destination accumulation window is discarded rather than left partially
    /// reduced.
    pub fn full_model_pending_gradient_transport_source(
        &self,
    ) -> Result<HierarchosPendingGradientTransportSource> {
        self.full_model_pending_gradient_transport_source_impl(true)
    }

    /// Capture a scaled replica gradient window for a data-parallel
    /// GradScaler reduction. Unlike the ordinary transport entrypoint this
    /// deliberately does not reject NaN/Inf on the replica: PyTorch AMP makes
    /// one overflow decision only after all data-parallel gradients have been
    /// reduced. The primary dynamic-loss-scaling finisher owns that global
    /// non-finite scan and will predicate AdamW plus the scaler transition.
    ///
    /// Metadata is still validated normally. Only the model-sized gradient
    /// payload is allowed to carry non-finite values through the Vulkan
    /// transport, preserving the exact signal needed by GradScaler.
    pub fn full_model_pending_gradient_transport_source_for_dynamic_loss_scaling(
        &self,
    ) -> Result<HierarchosPendingGradientTransportSource> {
        self.full_model_pending_gradient_transport_source_impl(false)
    }

    fn full_model_pending_gradient_transport_source_impl(
        &self,
        require_finite_gradients: bool,
    ) -> Result<HierarchosPendingGradientTransportSource> {
        if !self.full_model_accumulation_open {
            bail!("pending gradient transport source requires an open accumulation window");
        }
        let metadata = self.full_model_pending_gradient_metadata()?;
        if require_finite_gradients && self.pending_full_model_gradients_have_nonfinite()? {
            bail!("streamed gradient source contains non-finite values");
        }
        let source_direct_lm_gradient = self
            .full_model_direct_lm_gradient
            .context("open streamed source window is missing lm_head gradient topology")?;
        let source_lm_gradient =
            source_direct_lm_gradient.then(|| self.shared_lm_head.gradient_buffer().clone());
        let source_override = source_lm_gradient
            .as_ref()
            .map(|gradient| (LM_HEAD_WEIGHT_TENSOR_NAME, gradient));
        let optimizer = self
            .full_model_optimizer
            .pending_gradient_source_with_override(source_override)?;
        Ok(HierarchosPendingGradientTransportSource {
            device: self.device.clone(),
            metadata,
            optimizer,
        })
    }

    pub fn accumulate_full_model_pending_gradients_streamed_from(
        &mut self,
        replica: &HierarchosTrainingGraph,
        max_chunk_values: usize,
    ) -> Result<HierarchosGradientStreamStats> {
        let source = replica.full_model_pending_gradient_transport_source()?;
        self.accumulate_full_model_pending_gradients_streamed_from_source(&source, max_chunk_values)
    }

    /// Reduce a detached replica gradient source into this graph. The source
    /// owns cloned Vulkan gradient buffers and fixed-size merge metadata, so the
    /// non-`Sync` replica graph itself does not participate in transport.
    pub fn accumulate_full_model_pending_gradients_streamed_from_source(
        &mut self,
        source: &HierarchosPendingGradientTransportSource,
        max_chunk_values: usize,
    ) -> Result<HierarchosGradientStreamStats> {
        if max_chunk_values == 0 {
            bail!("streamed gradient transport chunk size must be positive");
        }
        let plan = self.plan_pending_gradient_merge(&source.metadata)?;

        let source_layout = source.optimizer.gradient_layout();
        let destination_layout = self.full_model_optimizer.gradient_layout();
        if source_layout != destination_layout {
            let mismatch = source_layout
                .iter()
                .zip(&destination_layout)
                .position(|(source, destination)| source != destination);
            bail!(
                "streamed gradient registry layout mismatch: source tensors={} destination tensors={} first mismatch={mismatch:?}",
                source_layout.len(),
                destination_layout.len()
            );
        }
        if source_layout.is_empty() {
            bail!("streamed gradient transport requires at least one optimizer tensor");
        }
        let destination_direct_lm_gradient = self
            .full_model_direct_lm_gradient
            .context("open streamed destination window is missing lm_head gradient topology")?;
        let destination_lm_gradient =
            destination_direct_lm_gradient.then(|| self.shared_lm_head.gradient_buffer().clone());
        let destination_override = destination_lm_gradient
            .as_ref()
            .map(|gradient| (LM_HEAD_WEIGHT_TENSOR_NAME, gradient));

        let largest_tensor = source_layout
            .iter()
            .map(|(_, len)| *len)
            .max()
            .context("streamed gradient registry unexpectedly has no tensor lengths")?;
        let chunk_capacity = max_chunk_values
            .min(self.optimizer_transport_chunk_values)
            .min(largest_tensor)
            .max(1);

        // Fast path: when both graphs are execution views of one Vulkan 1.1
        // device group, try to allocate a primary-memory transport window that
        // the replica can address through peer memory. Failure to prove COPY_DST
        // support is a capability miss, not a training failure: fall through to
        // the mature bounded host-visible pipeline before mutating gradients.
        let device_group_transport = if self.device.shares_logical_device_with(&source.device)
            && self.device.is_multi_physical_device_logical_device()
            && self.device.device_mask() != source.device.device_mask()
        {
            match (0..CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS)
                .map(|slot_index| {
                    DeviceGroupGradientTransportSlot::new(
                        &source.device,
                        &self.device,
                        chunk_capacity,
                        self.optimizer_transport_scratch_slots[slot_index].clone(),
                    )
                })
                .collect::<Result<Vec<_>>>()
            {
                Ok(slots) => Some(slots),
                Err(err) => {
                    eprintln!(
                        "hierarchos_vulkan_gradient_transport_fallback source_device={} destination_device={} attempted=device-group fallback=host-visible-staged-v2-pipelined reason={err:#}",
                        source.device.physical_device_index(),
                        self.device.physical_device_index(),
                    );
                    None
                }
            }
        } else {
            None
        };

        if let Some(mut transport_slots) = device_group_transport {
            let mut chunk_count = 0usize;
            let mut value_count = 0usize;
            let mut destination_mutated = false;
            let transport_result = (|| -> Result<()> {
                let mut source_chunk_index = 0usize;
                for (tensor_index, (_, tensor_len)) in source_layout.iter().enumerate() {
                    let mut offset = 0usize;
                    while offset < *tensor_len {
                        let len = chunk_capacity.min(*tensor_len - offset);
                        let slot_index = source_chunk_index % transport_slots.len();
                        let slot = &mut transport_slots[slot_index];

                        // Execute the transfer on the replica's physical-device
                        // mask. The destination resource is bound to the primary
                        // memory instance. Slot reuse is chained by a GPU-side
                        // returned->handoff semaphore round trip, so N+1 can be
                        // queued before the host joins N's command-buffer fences.
                        let mut source_commands = vulkan::ComputeBatch::new(&source.device)?;
                        source.optimizer.record_gradient_range_copy(
                            &mut source_commands,
                            tensor_index,
                            offset,
                            len,
                            &slot.peer_window,
                        )?;

                        // Consume the exact same primary-memory allocation from
                        // the primary device mask and accumulate it directly into
                        // the canonical optimizer gradient registry. No CPU fence
                        // or memcpy sits between the replica DMA and this dispatch.
                        let mut destination_commands = vulkan::ComputeBatch::new(&self.device)?;
                        self.full_model_optimizer
                            .record_accumulate_gradient_range_with_override(
                                &mut destination_commands,
                                tensor_index,
                                offset,
                                &slot.peer_window,
                                &slot.destination_scratch,
                                len,
                                destination_override,
                            )?;
                        let enqueued = slot.enqueue_roundtrip(
                            source_commands,
                            destination_commands,
                            len,
                            None,
                        )?;
                        let retired_len = enqueued.retire_previous()?;
                        if let Some(retired_len) = retired_len {
                            chunk_count = chunk_count
                                .checked_add(1)
                                .context("device-group gradient chunk counter overflow")?;
                            value_count = value_count
                                .checked_add(retired_len)
                                .context("device-group gradient value counter overflow")?;
                        }
                        destination_mutated = true;
                        source_chunk_index = source_chunk_index
                            .checked_add(1)
                            .context("device-group gradient source chunk counter overflow")?;
                        offset += len;
                    }
                }

                for slot in transport_slots.iter_mut() {
                    if let Some(retired_len) = slot.retire()? {
                        chunk_count = chunk_count
                            .checked_add(1)
                            .context("device-group gradient chunk counter overflow")?;
                        value_count = value_count
                            .checked_add(retired_len)
                            .context("device-group gradient value counter overflow")?;
                    }
                }
                if chunk_count != source_chunk_index {
                    bail!(
                        "device-group gradient pipeline retired {chunk_count} chunks after submitting {source_chunk_index}"
                    );
                }

                let mut commands = vulkan::ComputeBatch::new(&self.device)?;
                let ltm_cost_upload =
                    self.record_pending_gradient_merge_metadata(&mut commands, &plan)?;
                commands.submit()?;
                drop(ltm_cost_upload);
                Ok(())
            })();

            if let Err(err) = transport_result {
                let drain_result = transport_slots
                    .iter_mut()
                    .try_for_each(|slot| slot.retire().map(|_| ()));
                if let Err(drain_err) = drain_result {
                    return Err(err.context(format!(
                        "device-group gradient transport failed and draining in-flight GPU work also failed: {drain_err:#}"
                    )));
                }
                if destination_mutated {
                    match self.discard_full_model_accumulation_after_overflow() {
                        Ok(_) => {
                            return Err(err.context(
                                "device-group cross-adapter reduction failed; partial destination accumulation was discarded",
                            ));
                        }
                        Err(rollback_err) => {
                            return Err(err.context(format!(
                                "device-group cross-adapter reduction failed and destination rollback also failed: {rollback_err:#}"
                            )));
                        }
                    }
                }
                return Err(err);
            }

            self.commit_pending_gradient_merge(plan);
            return Ok(HierarchosGradientStreamStats {
                backend: VulkanGradientTransportBackend::DeviceGroup,
                tensor_count: source_layout.len(),
                chunk_count,
                value_count,
                max_chunk_values: chunk_capacity,
                pipeline_slots: CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS,
                persistent_transport_reused: false,
                peak_host_gradient_bytes: 0,
                peak_device_gradient_bytes: chunk_capacity
                    .checked_mul(std::mem::size_of::<f32>())
                    .and_then(|bytes| bytes.checked_mul(2))
                    .and_then(|bytes| bytes.checked_mul(CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS))
                    .context("device-group gradient device-byte count overflow")?,
                peak_host_heap_gradient_bytes: 0,
                queue_submissions: chunk_count
                    .checked_mul(2)
                    .and_then(|submissions| submissions.checked_add(1))
                    .context("device-group gradient submission count overflow")?,
            });
        }

        // Independent logical devices on the same physical/driver identity can
        // share an opaque external allocation. The destination graph retains a
        // two-slot transport across gradient windows, amortizing allocation,
        // handle import/export, and semaphore construction. Queue-family
        // ownership still moves entirely on the GPU: replica -> external ->
        // primary for reduction, then primary -> external -> replica before a
        // slot is recycled. Separate binary semaphore pairs carry the
        // forward-ready and return-ownership edges, so no host fence or memcpy
        // is required in the gradient data plane.
        let opaque_external_transport = if source
            .device
            .opaque_external_transport_candidate_with(&self.device)
        {
            match self.take_opaque_external_gradient_transport(&source.device, chunk_capacity) {
                Ok(transport) => Some(transport),
                Err(err) => {
                    eprintln!(
                        "hierarchos_vulkan_gradient_transport_fallback source_device={} destination_device={} attempted=opaque-external-memory fallback=host-visible-staged-v2-pipelined reason={err:#}",
                        source.device.physical_device_index(),
                        self.device.physical_device_index(),
                    );
                    None
                }
            }
        } else {
            None
        };

        if let Some((mut transport, persistent_transport_reused)) = opaque_external_transport {
            let transport_capacity = transport.chunk_capacity;
            let transport_slots = &mut transport.slots;
            let mut chunk_count = 0usize;
            let mut value_count = 0usize;
            let mut destination_mutated = false;
            let transport_result = (|| -> Result<()> {
                let mut source_chunk_index = 0usize;
                for (tensor_index, (_, tensor_len)) in source_layout.iter().enumerate() {
                    let mut offset = 0usize;
                    while offset < *tensor_len {
                        let len = chunk_capacity.min(*tensor_len - offset);
                        let slot_index = source_chunk_index % transport_slots.len();
                        let slot = &mut transport_slots[slot_index];

                        if slot.has_in_flight_work() {
                            if let Some(retired_len) = slot.retire()? {
                                chunk_count = chunk_count
                                    .checked_add(1)
                                    .context("opaque external gradient chunk counter overflow")?;
                                value_count = value_count
                                    .checked_add(retired_len)
                                    .context("opaque external gradient value counter overflow")?;
                            }
                        }

                        let mut source_commands = vulkan::ComputeBatch::new(&source.device)?;
                        if slot.source_requires_acquire {
                            source_commands.acquire_buffer_from_external(
                                &slot.source_window,
                                slot.capacity_values,
                            )?;
                        }
                        source.optimizer.record_gradient_range_copy(
                            &mut source_commands,
                            tensor_index,
                            offset,
                            len,
                            &slot.source_window,
                        )?;
                        source_commands.release_buffer_to_external(
                            &slot.source_window,
                            slot.capacity_values,
                        )?;
                        slot.source_submission = Some(if slot.source_requires_acquire {
                            source_commands.submit_async_wait_signal_raw_binary_semaphores(
                                slot.returned.destination_semaphore(),
                                slot.ready.source_semaphore(),
                            )?
                        } else {
                            source_commands.submit_async_signal_raw_binary_semaphore(
                                slot.ready.source_semaphore(),
                            )?
                        });

                        let mut destination_commands = vulkan::ComputeBatch::new(&self.device)?;
                        destination_commands.acquire_buffer_from_external(
                            &slot.destination_window,
                            slot.capacity_values,
                        )?;
                        self.full_model_optimizer
                            .record_accumulate_gradient_range_with_override(
                                &mut destination_commands,
                                tensor_index,
                                offset,
                                &slot.destination_window,
                                &slot.destination_scratch,
                                len,
                                destination_override,
                            )?;
                        destination_commands.release_buffer_to_external(
                            &slot.destination_window,
                            slot.capacity_values,
                        )?;
                        slot.destination_submission = Some(
                            destination_commands.submit_async_wait_signal_raw_binary_semaphores(
                                slot.ready.destination_semaphore(),
                                slot.returned.source_semaphore(),
                            )?,
                        );
                        slot.source_requires_acquire = true;
                        slot.in_flight_len = Some(len);
                        destination_mutated = true;
                        source_chunk_index = source_chunk_index
                            .checked_add(1)
                            .context("opaque external gradient source chunk counter overflow")?;
                        offset += len;
                    }
                }

                for slot in transport_slots.iter_mut() {
                    if let Some(retired_len) = slot.retire()? {
                        chunk_count = chunk_count
                            .checked_add(1)
                            .context("opaque external gradient chunk counter overflow")?;
                        value_count = value_count
                            .checked_add(retired_len)
                            .context("opaque external gradient value counter overflow")?;
                    }
                }
                if chunk_count != source_chunk_index {
                    bail!(
                        "opaque external gradient pipeline retired {chunk_count} chunks after submitting {source_chunk_index}"
                    );
                }

                let mut commands = vulkan::ComputeBatch::new(&self.device)?;
                let ltm_cost_upload =
                    self.record_pending_gradient_merge_metadata(&mut commands, &plan)?;
                commands.submit()?;
                drop(ltm_cost_upload);
                Ok(())
            })();

            if let Err(err) = transport_result {
                let drain_result = transport_slots
                    .iter_mut()
                    .try_for_each(|slot| slot.retire().map(|_| ()));
                if let Err(drain_err) = drain_result {
                    return Err(err.context(format!(
                        "opaque external gradient transport failed and draining in-flight GPU work also failed: {drain_err:#}"
                    )));
                }
                if destination_mutated {
                    match self.discard_full_model_accumulation_after_overflow() {
                        Ok(_) => {
                            return Err(err.context(
                                "opaque external cross-adapter reduction failed; partial destination accumulation was discarded",
                            ));
                        }
                        Err(rollback_err) => {
                            return Err(err.context(format!(
                                "opaque external cross-adapter reduction failed and destination rollback also failed: {rollback_err:#}"
                            )));
                        }
                    }
                }
                return Err(err);
            }

            self.commit_pending_gradient_merge(plan);
            self.opaque_external_gradient_transports.push(transport);
            return Ok(HierarchosGradientStreamStats {
                backend: VulkanGradientTransportBackend::OpaqueExternalMemory,
                tensor_count: source_layout.len(),
                chunk_count,
                value_count,
                max_chunk_values: chunk_capacity,
                pipeline_slots: CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS,
                persistent_transport_reused,
                peak_host_gradient_bytes: 0,
                peak_device_gradient_bytes: transport_capacity
                    .checked_mul(std::mem::size_of::<f32>())
                    .and_then(|bytes| bytes.checked_mul(2))
                    .and_then(|bytes| bytes.checked_mul(CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS))
                    .context("opaque external gradient device-byte count overflow")?,
                peak_host_heap_gradient_bytes: 0,
                queue_submissions: chunk_count
                    .checked_mul(2)
                    .and_then(|submissions| submissions.checked_add(1))
                    .context("opaque external gradient submission count overflow")?,
            });
        }

        let mut transport_slots = (0..CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS)
            .map(|slot_index| {
                PendingGradientTransportSlot::new(
                    &source.device,
                    &self.device,
                    chunk_capacity,
                    self.optimizer_transport_upload_slots[slot_index].clone(),
                    self.optimizer_transport_scratch_slots[slot_index].clone(),
                )
            })
            .collect::<Result<Vec<_>>>()?;

        let mut chunk_count = 0usize;
        let mut value_count = 0usize;
        let mut destination_mutated = false;
        let transport_result = (|| -> Result<()> {
            let mut source_chunk_index = 0usize;
            for (tensor_index, (_, tensor_len)) in source_layout.iter().enumerate() {
                let mut offset = 0usize;
                while offset < *tensor_len {
                    let len = chunk_capacity.min(*tensor_len - offset);
                    let slot_index = source_chunk_index % transport_slots.len();
                    let slot = &mut transport_slots[slot_index];
                    if slot.pending.is_some() || slot.source_submission.is_some() {
                        bail!(
                            "streamed gradient pipeline attempted to reuse source slot {slot_index} before retirement"
                        );
                    }
                    let mut source_commands = vulkan::ComputeBatch::new(&source.device)?;
                    source.optimizer.record_gradient_range_readback(
                        &mut source_commands,
                        tensor_index,
                        offset,
                        len,
                        &slot.source_readback,
                    )?;
                    slot.source_submission = Some(source_commands.submit_async()?);
                    slot.pending = Some(PendingGradientTransportChunk {
                        tensor_index,
                        offset,
                        len,
                    });

                    // Submit the next source copy before retiring the previous
                    // slot. On distinct adapters this lets source DMA/transfer
                    // overlap the primary's prior reduction command stream.
                    if source_chunk_index > 0 {
                        let previous_slot_index = (source_chunk_index - 1) % transport_slots.len();
                        if let Some(flushed_len) = self.flush_pending_gradient_transport_slot(
                            &mut transport_slots[previous_slot_index],
                            destination_override,
                        )? {
                            destination_mutated = true;
                            chunk_count = chunk_count
                                .checked_add(1)
                                .context("streamed gradient chunk counter overflow")?;
                            value_count = value_count
                                .checked_add(flushed_len)
                                .context("streamed gradient value counter overflow")?;
                        }
                    }

                    source_chunk_index = source_chunk_index
                        .checked_add(1)
                        .context("streamed gradient source chunk counter overflow")?;
                    offset += len;
                }
            }

            if source_chunk_index > 0 {
                let final_slot_index = (source_chunk_index - 1) % transport_slots.len();
                if let Some(flushed_len) = self.flush_pending_gradient_transport_slot(
                    &mut transport_slots[final_slot_index],
                    destination_override,
                )? {
                    destination_mutated = true;
                    chunk_count = chunk_count
                        .checked_add(1)
                        .context("streamed gradient chunk counter overflow")?;
                    value_count = value_count
                        .checked_add(flushed_len)
                        .context("streamed gradient value counter overflow")?;
                }
            }

            for slot in &mut transport_slots {
                slot.wait_destination()?;
            }
            if chunk_count != source_chunk_index {
                bail!(
                    "streamed gradient pipeline retired {chunk_count} chunks after submitting {source_chunk_index}"
                );
            }

            let mut commands = vulkan::ComputeBatch::new(&self.device)?;
            let ltm_cost_upload =
                self.record_pending_gradient_merge_metadata(&mut commands, &plan)?;
            commands.submit()?;
            drop(ltm_cost_upload);
            Ok(())
        })();

        if let Err(err) = transport_result {
            if destination_mutated {
                match self.discard_full_model_accumulation_after_overflow() {
                    Ok(_) => {
                        return Err(err.context(
                            "streamed cross-adapter reduction failed; partial destination accumulation was discarded",
                        ));
                    }
                    Err(rollback_err) => {
                        return Err(err.context(format!(
                            "streamed cross-adapter reduction failed and destination rollback also failed: {rollback_err:#}"
                        )));
                    }
                }
            }
            return Err(err);
        }

        self.commit_pending_gradient_merge(plan);
        Ok(HierarchosGradientStreamStats {
            backend: VulkanGradientTransportBackend::HostVisibleStagedV2Pipelined,
            tensor_count: source_layout.len(),
            chunk_count,
            value_count,
            max_chunk_values: chunk_capacity,
            pipeline_slots: CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS,
            persistent_transport_reused: false,
            peak_host_gradient_bytes: chunk_capacity
                .checked_mul(std::mem::size_of::<f32>())
                .and_then(|bytes| bytes.checked_mul(2))
                .and_then(|bytes| bytes.checked_mul(CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS))
                .context("streamed gradient host-byte count overflow")?,
            peak_device_gradient_bytes: chunk_capacity
                .checked_mul(std::mem::size_of::<f32>())
                .and_then(|bytes| bytes.checked_mul(2))
                .and_then(|bytes| bytes.checked_mul(CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS))
                .context("streamed gradient device-byte count overflow")?,
            peak_host_heap_gradient_bytes: 0,
            queue_submissions: chunk_count
                .checked_mul(2)
                .and_then(|submissions| submissions.checked_add(1))
                .context("streamed gradient submission count overflow")?,
        })
    }

    fn validate_streamed_replica_state_source(
        &self,
        source: &HierarchosFullModelReplicaTransportSource,
    ) -> Result<()> {
        if self.full_model_accumulation_open {
            bail!("streamed replica state requires a closed destination optimizer window");
        }
        if self.config.architecture_revision != source.architecture_revision {
            bail!(
                "replica architecture {:?} does not match source {:?}",
                self.config.architecture_revision,
                source.architecture_revision
            );
        }
        if self.training_precision_policy.label() != source.training_precision_policy {
            bail!(
                "replica precision {:?} does not match source {:?}",
                self.training_precision_policy.label(),
                source.training_precision_policy
            );
        }
        if self.full_model_optimizer.gradient_layout() != source.optimizer.gradient_layout() {
            bail!("streamed replica optimizer registries do not match");
        }
        source.ltm_alignment_controller.validate_policy()?;
        if source.ltm_alignment_controller.sampled_rows_in_window != 0
            || source
                .ltm_alignment_controller
                .sampled_rows_in_controller_microbatch
                != 0
        {
            bail!("closed streamed replica source has live LTM accumulation counters");
        }
        let active_policy = &self.ltm_alignment_controller;
        let source_policy = &source.ltm_alignment_controller;
        if source_policy.weight != active_policy.weight
            || source_policy.stride != active_policy.stride
            || source_policy.min_updates != active_policy.min_updates
            || source_policy.ready_threshold != active_policy.ready_threshold
            || source_policy.ema_decay != active_policy.ema_decay
            || source_policy.writer_max_norm != active_policy.writer_max_norm
        {
            bail!("streamed replica LTM alignment policy does not match destination");
        }
        Ok(())
    }

    /// Finalize the host control plane after a device-group stream that copied
    /// Adam clocks directly into the replica's device-resident step buffers.
    /// The output trainer's legacy host-only step mirror is intentionally left
    /// stale: canonical full-model replica work does not consume that counter,
    /// and forcing it exact here would reintroduce the per-window CPU readback
    /// this transport exists to remove.
    fn finalize_streamed_replica_state_device_step_metadata_from(
        &mut self,
        source: &HierarchosFullModelReplicaTransportSource,
    ) -> Result<()> {
        self.finalize_streamed_replica_state_non_optimizer_metadata_from(source)
    }

    fn finalize_streamed_replica_state_non_optimizer_metadata_from(
        &mut self,
        source: &HierarchosFullModelReplicaTransportSource,
    ) -> Result<()> {
        match (self.token_frontend.is_some(), source.training_step) {
            (true, Some(step)) => self.set_training_step(step)?,
            (true, None) => bail!("frontend-enabled replica source is missing training_step"),
            (false, Some(_)) => {
                bail!("frontend-disabled replica source unexpectedly carries training_step")
            }
            (false, None) => {}
        }
        self.ltm_alignment_controller = source.ltm_alignment_controller.clone();
        self.ltm_alignment_device_control
            .invalidate_device_authority();
        self.sync_ltm_alignment_config();
        self.full_model_accumulation_normalization = None;
        self.full_model_direct_lm_gradient = None;
        self.val_proj_active_in_window = false;
        self.ltm_alignment_pytorch_tbptt_weighting_in_window = None;
        self.ltm_alignment_readback_pending = false;
        Ok(())
    }

    /// Capture a closed optimizer boundary as an immutable transport-only
    /// source. Vulkan tensor storage is retained by cloned `GpuBuffer` handles;
    /// only the tiny control plane is copied to host values.
    pub fn full_model_replica_transport_source(
        &self,
    ) -> Result<HierarchosFullModelReplicaTransportSource> {
        if self.full_model_accumulation_open {
            bail!("cannot capture a replica transport source while accumulation is open");
        }
        if self.ltm_alignment_controller.sampled_rows_in_window != 0
            || self
                .ltm_alignment_controller
                .sampled_rows_in_controller_microbatch
                != 0
        {
            bail!("closed replica transport source has live LTM accumulation counters");
        }
        self.ltm_alignment_controller.validate_policy()?;
        let registry = full_model_named_trainables(
            &self.h_recurrent,
            &self.l_recurrent,
            &self.projections,
            self.token_frontend.as_ref(),
            &self.output,
        )?;
        let trainables = registry
            .iter()
            .map(NamedTrainable::as_trainable)
            .collect::<Vec<_>>();
        let optimizer = self
            .full_model_optimizer
            .replica_state_source(&trainables)?;
        Ok(HierarchosFullModelReplicaTransportSource {
            device: self.device.clone(),
            architecture_revision: self.config.architecture_revision.clone(),
            training_precision_policy: self.training_precision_policy.label().to_string(),
            optimizer,
            training_step: self.training_step(),
            ltm_alignment_controller: self.ltm_alignment_controller.clone(),
        })
    }

    /// Number of raw u32 words needed to transport the canonical AdamW global
    /// clock plus every registered per-parameter clock. This is pure topology
    /// metadata and never synchronizes device-owned optimizer state.
    pub fn full_model_optimizer_step_metadata_words(&self) -> usize {
        self.full_model_optimizer.tensor_count() + 1
    }

    /// Stream a closed primary replica state directly into this graph without
    /// materializing model-sized parameter or AdamW-moment snapshots on the
    /// host. Parameters, exp_avg, and exp_avg_sq share the canonical 95-slot
    /// optimizer registry and are transferred through two bounded slots.
    ///
    /// Returns `Ok(None)` when the device pair has no direct Vulkan transport;
    /// callers can then reuse the portable `HierarchosFullModelReplicaState`
    /// fallback. Step counters, curriculum position, and LTM-controller state
    /// remain a deliberately tiny CPU-side control plane.
    pub fn stream_full_model_replica_state_from_source(
        &mut self,
        source: &HierarchosFullModelReplicaTransportSource,
        max_chunk_values: usize,
    ) -> Result<Option<HierarchosReplicaStateStreamStats>> {
        self.stream_full_model_replica_state_from_source_impl(source, max_chunk_values, None)
    }

    /// Stream replica state while retiring this worker's per-range generation
    /// leases as soon as the Vulkan transfer fence for all three state planes
    /// of each range has completed. This is the broadcast half of chunk-level
    /// AdamW wavefront retirement.
    pub fn stream_full_model_replica_state_from_source_with_range_retirement(
        &mut self,
        source: &HierarchosFullModelReplicaTransportSource,
        max_chunk_values: usize,
        retirement: &mut HierarchosReplicaStateRangeRetirement,
    ) -> Result<Option<HierarchosReplicaStateStreamStats>> {
        self.stream_full_model_replica_state_from_source_impl(
            source,
            max_chunk_values,
            Some(retirement),
        )
    }

    /// Stream through a device-group transport whose peer buffers, semaphore
    /// round trips, independent source queue lane, and future AdamW retirement
    /// values were all established before the worker job was launched. Unlike
    /// the portable streaming entrypoints, this path is deliberately infallible
    /// with respect to backend selection: once its waits are published, falling
    /// back to source-queue host readback could sit behind AdamW's predeclared
    /// wait and deadlock. Runtime failures therefore abort the worker instead of
    /// changing transports underneath an already-published dependency graph.
    pub fn stream_full_model_replica_state_from_source_with_predeclared_timeline(
        &mut self,
        source: &HierarchosFullModelReplicaTransportSource,
        max_chunk_values: usize,
        transport: &mut HierarchosReplicaStateDeviceGroupTransport,
        reservation: &mut HierarchosReplicaStateTimelineReservation,
    ) -> Result<HierarchosReplicaStateStreamStats> {
        if max_chunk_values == 0 {
            bail!("predeclared replica-state chunk size must be positive");
        }
        self.validate_streamed_replica_state_source(source)?;
        anyhow::ensure!(
            source
                .device
                .shares_logical_device_with(&transport.source_signal_device)
                && source.device.device_mask() == transport.source_device_mask,
            "predeclared replica-state transport does not match source device"
        );
        anyhow::ensure!(
            self.device.device_mask() == transport.destination_device_mask
                && self
                    .device
                    .shares_logical_device_with(&transport.source_signal_device),
            "predeclared replica-state transport does not match destination device"
        );
        anyhow::ensure!(
            reservation.inner.destination_device_mask == self.device.device_mask(),
            "predeclared replica-state timeline does not match destination device"
        );
        anyhow::ensure!(
            Arc::ptr_eq(&reservation.inner, &transport.retirement_timeline.inner),
            "predeclared replica-state reservation belongs to a different persistent timeline"
        );

        let layout = source.optimizer.gradient_layout();
        let largest_tensor = layout
            .iter()
            .map(|(_, len)| *len)
            .max()
            .context("predeclared replica-state registry unexpectedly has no tensors")?;
        let chunk_capacity = max_chunk_values
            .min(self.optimizer_transport_chunk_values)
            .min(largest_tensor)
            .max(1);
        anyhow::ensure!(
            transport.chunk_capacity >= chunk_capacity,
            "predeclared replica-state transport capacity {} is smaller than required {chunk_capacity}",
            transport.chunk_capacity
        );
        anyhow::ensure!(
            transport.step_metadata_peer_window.f32_capacity()
                >= source.optimizer.step_metadata_word_count(),
            "predeclared replica-state AdamW metadata transport capacity {} is smaller than required {} words",
            transport.step_metadata_peer_window.f32_capacity(),
            source.optimizer.step_metadata_word_count(),
        );
        let state_range_count = source.optimizer.state_chunk_count(chunk_capacity)?;
        anyhow::ensure!(
            reservation.range_count() == state_range_count,
            "predeclared replica-state timeline reserved {} ranges; stream requires {state_range_count}",
            reservation.range_count()
        );
        anyhow::ensure!(
            !transport.slots.is_empty(),
            "predeclared replica-state transport has no pipeline slots"
        );
        // Previous generations retain only a source-generation owner plus the
        // mirror-refresh tail dependency. Polling that tail also reaps completed
        // transient submission resources from the device-level timeline arena.
        transport.generation_tail_ring.reap_completed()?;

        let destination_registry = full_model_named_trainables(
            &self.h_recurrent,
            &self.l_recurrent,
            &self.projections,
            self.token_frontend.as_ref(),
            &self.output,
        )?;
        let destination_trainables = destination_registry
            .iter()
            .map(NamedTrainable::as_trainable)
            .collect::<Vec<_>>();
        let planes = [
            RwkvReplicaStatePlane::Parameter,
            RwkvReplicaStatePlane::ExpAvg,
            RwkvReplicaStatePlane::ExpAvgSq,
        ];
        let persistent_transport_reused = transport.used;
        let transport_slots = &mut transport.slots;
        let source_generation_wait = source.optimizer.generation_ready_after();
        let mut value_count = 0usize;
        let mut source_chunk_index = 0usize;
        let mut state_range_index = 0usize;

        for (tensor_index, (_, tensor_len)) in layout.iter().enumerate() {
            let mut offset = 0usize;
            while offset < *tensor_len {
                let len = chunk_capacity.min(*tensor_len - offset);
                let current_range_index = state_range_index;
                for plane in planes {
                    let slot_index = source_chunk_index % transport_slots.len();
                    let slot = &mut transport_slots[slot_index];

                    // This view carries the primary physical-device mask but
                    // selects the replica's queue lane. AdamW can therefore be
                    // queued on the primary lane before this worker arrives.
                    let mut source_commands =
                        vulkan::ComputeBatch::new(&transport.source_signal_device)?;
                    source.optimizer.record_range_copy(
                        &mut source_commands,
                        tensor_index,
                        plane,
                        offset,
                        len,
                        &slot.peer_window,
                    )?;

                    let mut destination_commands = vulkan::ComputeBatch::new(&self.device)?;
                    self.full_model_optimizer.record_replica_state_range_write(
                        &mut destination_commands,
                        &destination_trainables,
                        tensor_index,
                        plane,
                        offset,
                        len,
                        &slot.peer_window,
                    )?;
                    // The first range's final source batch also snapshots every
                    // global/per-slot Adam clock into a dedicated tiny peer
                    // window. Its retirement signal is emitted only after these
                    // reads complete, so primary AdamW may advance device_step
                    // immediately afterward without racing replica metadata.
                    // Destination clock writes ride the same handoff and remain
                    // queue-ordered before the replica's mirror-refresh tail.
                    if current_range_index == 0 && plane == RwkvReplicaStatePlane::ExpAvgSq {
                        source.optimizer.record_step_metadata_pack(
                            &mut source_commands,
                            &transport.step_metadata_peer_window,
                        )?;
                        self.full_model_optimizer
                            .record_replica_step_metadata_write(
                                &mut destination_commands,
                                &source.optimizer,
                                &transport.step_metadata_peer_window,
                            )?;
                    }
                    let retirement_signal = if plane == RwkvReplicaStatePlane::ExpAvgSq {
                        Some(reservation.signal_for_range(current_range_index)?)
                    } else {
                        None
                    };
                    slot.enqueue_roundtrip(
                        source_commands,
                        destination_commands,
                        (source_chunk_index == 0)
                            .then_some(source_generation_wait.as_ref())
                            .flatten(),
                        retirement_signal
                            .as_ref()
                            .map(|(semaphore, value)| (semaphore, *value)),
                    )?;
                    if retirement_signal.is_some() {
                        reservation.mark_signal_submitted(current_range_index)?;
                    }
                    source_chunk_index = source_chunk_index
                        .checked_add(1)
                        .context("predeclared replica-state source chunk counter overflow")?;
                    value_count = value_count
                        .checked_add(len)
                        .context("predeclared replica-state value counter overflow")?;
                }
                state_range_index = state_range_index
                    .checked_add(1)
                    .context("predeclared replica-state range counter overflow")?;
                offset += len;
            }
        }

        anyhow::ensure!(
            state_range_index == state_range_count,
            "predeclared replica-state stream traversed {state_range_index} ranges; expected {state_range_count}"
        );
        reservation.ensure_fully_submitted()?;

        // The mirror refresh shares the replica queue with every destination
        // write. Retain only its queue-completion dependency plus a clone of the
        // captured source generation. Its command/descriptor/query resources are
        // already owned by DeviceInner, so the worker can return without a
        // submission-object retirement ring. Any subsequent replica compute
        // submission lands after this refresh on the same queue.
        let mut refresh = vulkan::ComputeBatch::new(&self.device)?;
        self.full_model_optimizer
            .record_refresh_parameter_mirrors(&mut refresh, &destination_trainables)?;
        let refresh_submission = refresh.submit_async()?;
        let refresh_completion = refresh_submission.timeline_wait().context(
            "predeclared replica-state mirror refresh unexpectedly used fence completion",
        )?;
        drop(refresh_submission);
        transport
            .generation_tail_ring
            .push(DeviceGroupGenerationTailRetirement {
                completion: refresh_completion,
                _source_owner: source.clone(),
            })?;
        let chunk_count = source_chunk_index;
        drop(destination_trainables);
        drop(destination_registry);
        self.finalize_streamed_replica_state_device_step_metadata_from(source)?;
        transport.used = true;
        Ok(HierarchosReplicaStateStreamStats {
            backend: VulkanGradientTransportBackend::DeviceGroup,
            tensor_count: layout.len(),
            chunk_count,
            value_count,
            max_chunk_values: chunk_capacity,
            pipeline_slots: transport_slots.len(),
            persistent_transport_reused,
            peak_host_state_bytes: 0,
            peak_device_state_bytes: transport
                .chunk_capacity
                .checked_mul(std::mem::size_of::<f32>())
                .and_then(|bytes| bytes.checked_mul(transport_slots.len()))
                .context("predeclared replica-state device-byte count overflow")?,
            queue_submissions: chunk_count
                .checked_mul(2)
                .and_then(|submissions| submissions.checked_add(1))
                .context("predeclared replica-state submission count overflow")?,
        })
    }

    fn stream_full_model_replica_state_from_source_impl(
        &mut self,
        source: &HierarchosFullModelReplicaTransportSource,
        max_chunk_values: usize,
        mut retirement: Option<&mut HierarchosReplicaStateRangeRetirement>,
    ) -> Result<Option<HierarchosReplicaStateStreamStats>> {
        if max_chunk_values == 0 {
            bail!("streamed replica-state chunk size must be positive");
        }
        self.validate_streamed_replica_state_source(source)?;

        let layout = source.optimizer.gradient_layout();
        let largest_tensor = layout
            .iter()
            .map(|(_, len)| *len)
            .max()
            .context("streamed replica-state registry unexpectedly has no tensors")?;
        let chunk_capacity = max_chunk_values.min(largest_tensor).max(1);
        let state_range_count = source.optimizer.state_chunk_count(chunk_capacity)?;
        if let Some(retirement) = retirement.as_deref() {
            anyhow::ensure!(
                retirement.optimizer.range_count() == state_range_count,
                "replica range-retirement plan has {} ranges; stream requires {state_range_count}",
                retirement.optimizer.range_count()
            );
        }
        let planes = [
            RwkvReplicaStatePlane::Parameter,
            RwkvReplicaStatePlane::ExpAvg,
            RwkvReplicaStatePlane::ExpAvgSq,
        ];

        let device_group_candidate = source.device.shares_logical_device_with(&self.device)
            && source.device.is_multi_physical_device_logical_device()
            && source.device.device_mask() != self.device.device_mask();
        let opaque_external_transport = if !device_group_candidate
            && source
                .device
                .opaque_external_transport_candidate_with(&self.device)
        {
            match self.take_opaque_external_gradient_transport(&source.device, chunk_capacity) {
                Ok(transport) => Some(transport),
                Err(err) => {
                    eprintln!(
                        "hierarchos_vulkan_replica_state_transport_fallback source_device={} destination_device={} attempted=opaque-external-memory reason={err:#}",
                        source.device.physical_device_index(),
                        self.device.physical_device_index(),
                    );
                    None
                }
            }
        } else {
            None
        };
        let destination_registry = full_model_named_trainables(
            &self.h_recurrent,
            &self.l_recurrent,
            &self.projections,
            self.token_frontend.as_ref(),
            &self.output,
        )?;
        let destination_trainables = destination_registry
            .iter()
            .map(NamedTrainable::as_trainable)
            .collect::<Vec<_>>();

        let device_group_transport = if device_group_candidate {
            match (0..CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS)
                .map(|slot_index| {
                    DeviceGroupGradientTransportSlot::new(
                        &source.device,
                        &self.device,
                        chunk_capacity,
                        self.optimizer_transport_scratch_slots[slot_index].clone(),
                    )
                })
                .collect::<Result<Vec<_>>>()
            {
                Ok(slots) => Some(slots),
                Err(err) => {
                    eprintln!(
                        "hierarchos_vulkan_replica_state_transport_fallback source_device={} destination_device={} attempted=device-group reason={err:#}",
                        source.device.physical_device_index(),
                        self.device.physical_device_index(),
                    );
                    None
                }
            }
        } else {
            None
        };

        if let Some(mut transport_slots) = device_group_transport {
            let step_metadata_words = source.optimizer.step_metadata_word_count();
            let step_metadata_peer_window = GpuBuffer::uninitialized_device_group_peer_f32(
                &self.device,
                &source.device,
                step_metadata_words,
            )?;
            let mut chunk_count = 0usize;
            let mut value_count = 0usize;
            let mut source_chunk_index = 0usize;
            let mut state_range_index = 0usize;
            let mut pending_retirements = vec![None; transport_slots.len()];
            for (tensor_index, (_, tensor_len)) in layout.iter().enumerate() {
                let mut offset = 0usize;
                while offset < *tensor_len {
                    let len = chunk_capacity.min(*tensor_len - offset);
                    let current_range_index = state_range_index;
                    for plane in planes {
                        let len = chunk_capacity.min(*tensor_len - offset);
                        let slot_index = source_chunk_index % transport_slots.len();
                        let slot = &mut transport_slots[slot_index];

                        let mut source_commands = vulkan::ComputeBatch::new(&source.device)?;
                        source.optimizer.record_range_copy(
                            &mut source_commands,
                            tensor_index,
                            plane,
                            offset,
                            len,
                            &slot.peer_window,
                        )?;

                        let mut destination_commands = vulkan::ComputeBatch::new(&self.device)?;
                        self.full_model_optimizer.record_replica_state_range_write(
                            &mut destination_commands,
                            &destination_trainables,
                            tensor_index,
                            plane,
                            offset,
                            len,
                            &slot.peer_window,
                        )?;
                        if current_range_index == 0 && plane == RwkvReplicaStatePlane::ExpAvgSq {
                            // Capture AdamW's global/per-slot clocks before the
                            // first state range can retire. A dedicated peer
                            // window keeps the metadata out of the tensor payload
                            // while preserving the same GPU handoff dependency.
                            source.optimizer.record_step_metadata_pack(
                                &mut source_commands,
                                &step_metadata_peer_window,
                            )?;
                            self.full_model_optimizer
                                .record_replica_step_metadata_write(
                                    &mut destination_commands,
                                    &source.optimizer,
                                    &step_metadata_peer_window,
                                )?;
                        }
                        let enqueued = slot.enqueue_roundtrip(
                            source_commands,
                            destination_commands,
                            len,
                            None,
                        )?;
                        let source_retirement_wait = enqueued.source_retirement_wait();
                        let mut defer_current_cpu_retirement = false;
                        if plane == RwkvReplicaStatePlane::ExpAvgSq {
                            if let (Some(retirement), Some(wait)) =
                                (retirement.as_deref_mut(), source_retirement_wait)
                            {
                                // Source submissions for all three planes use
                                // the same primary queue. Reaching the final
                                // exp_avg_sq handoff therefore implies the
                                // parameter and exp_avg source reads for this
                                // range are earlier in queue order. Publish the
                                // timeline value before joining any previous
                                // slot fences so AdamW can immediately enqueue
                                // its own GPU-side wait.
                                retirement.optimizer.retire_after_device_group_timeline(
                                    current_range_index,
                                    wait,
                                )?;
                            } else if retirement.is_some() {
                                // Binary device-group semaphores cannot be
                                // consumed by both the destination and AdamW.
                                // Keep the established CPU fence retirement on
                                // drivers without timeline semaphore support.
                                defer_current_cpu_retirement = true;
                            }
                        }
                        let retired_len = enqueued.retire_previous()?;
                        if let Some(retired_len) = retired_len {
                            chunk_count = chunk_count
                                .checked_add(1)
                                .context("device-group replica-state chunk counter overflow")?;
                            value_count = value_count
                                .checked_add(retired_len)
                                .context("device-group replica-state value counter overflow")?;
                            if let Some(retired_range) = pending_retirements[slot_index].take() {
                                if let Some(retirement) = retirement.as_deref_mut() {
                                    retirement.optimizer.retire(retired_range)?;
                                }
                            }
                        }
                        if defer_current_cpu_retirement {
                            pending_retirements[slot_index] = Some(current_range_index);
                        }
                        source_chunk_index = source_chunk_index
                            .checked_add(1)
                            .context("device-group replica-state source chunk counter overflow")?;
                    }
                    state_range_index = state_range_index
                        .checked_add(1)
                        .context("device-group replica-state range counter overflow")?;
                    offset += len;
                }
            }
            // Join every remaining transfer before retiring any final range.
            // With two pipeline slots the last range's exp_avg_sq can occupy
            // one slot while exp_avg is still in flight on the other; retiring
            // inline with the first slot's join would let AdamW mutate that
            // range before all three state planes had drained.
            for slot in transport_slots.iter_mut() {
                if let Some(retired_len) = slot.retire()? {
                    chunk_count = chunk_count
                        .checked_add(1)
                        .context("device-group replica-state chunk counter overflow")?;
                    value_count = value_count
                        .checked_add(retired_len)
                        .context("device-group replica-state value counter overflow")?;
                }
            }
            for retired_range in pending_retirements.iter_mut().filter_map(Option::take) {
                if let Some(retirement) = retirement.as_deref_mut() {
                    retirement.optimizer.retire(retired_range)?;
                }
            }
            if chunk_count != source_chunk_index {
                bail!(
                    "device-group replica-state pipeline retired {chunk_count} chunks after submitting {source_chunk_index}"
                );
            }
            anyhow::ensure!(
                state_range_index == state_range_count,
                "device-group replica-state stream traversed {state_range_index} ranges; expected {state_range_count}"
            );
            let mut refresh = vulkan::ComputeBatch::new(&self.device)?;
            self.full_model_optimizer
                .record_refresh_parameter_mirrors(&mut refresh, &destination_trainables)?;
            refresh.submit()?;
            drop(destination_trainables);
            drop(destination_registry);
            self.finalize_streamed_replica_state_device_step_metadata_from(source)?;
            return Ok(Some(HierarchosReplicaStateStreamStats {
                backend: VulkanGradientTransportBackend::DeviceGroup,
                tensor_count: layout.len(),
                chunk_count,
                value_count,
                max_chunk_values: chunk_capacity,
                pipeline_slots: CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS,
                persistent_transport_reused: false,
                peak_host_state_bytes: 0,
                peak_device_state_bytes: chunk_capacity
                    .checked_mul(std::mem::size_of::<f32>())
                    .and_then(|bytes| bytes.checked_mul(2))
                    .and_then(|bytes| bytes.checked_mul(CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS))
                    .context("device-group replica-state device-byte count overflow")?,
                queue_submissions: chunk_count
                    .checked_mul(2)
                    .and_then(|submissions| submissions.checked_add(1))
                    .context("device-group replica-state submission count overflow")?,
            }));
        }

        let Some((mut transport, persistent_transport_reused)) = opaque_external_transport else {
            return Ok(None);
        };
        let step_metadata_words = source.optimizer.step_metadata_word_count();
        transport
            .ensure_step_metadata_capacity(step_metadata_words)
            .context("preparing opaque external AdamW step-metadata transport")?;
        let step_metadata_source_window = transport
            .step_metadata_source_window
            .as_ref()
            .context("opaque external step-metadata source window is missing")?
            .clone();
        let step_metadata_destination_window = transport
            .step_metadata_destination_window
            .as_ref()
            .context("opaque external step-metadata destination window is missing")?
            .clone();
        let mut step_metadata_source_requires_acquire =
            transport.step_metadata_source_requires_acquire;
        let transport_capacity = transport.chunk_capacity;
        let transport_slots = &mut transport.slots;
        let mut chunk_count = 0usize;
        let mut value_count = 0usize;
        let mut source_chunk_index = 0usize;
        let mut state_range_index = 0usize;
        let mut pending_retirements = vec![None; transport_slots.len()];
        let transport_result = (|| -> Result<()> {
            for (tensor_index, (_, tensor_len)) in layout.iter().enumerate() {
                let mut offset = 0usize;
                while offset < *tensor_len {
                    let len = chunk_capacity.min(*tensor_len - offset);
                    let current_range_index = state_range_index;
                    for plane in planes {
                        let len = chunk_capacity.min(*tensor_len - offset);
                        let slot_index = source_chunk_index % transport_slots.len();
                        let slot = &mut transport_slots[slot_index];
                        if slot.has_in_flight_work() {
                            if let Some(retired_len) = slot.retire()? {
                                chunk_count = chunk_count
                                    .checked_add(1)
                                    .context("opaque replica-state chunk counter overflow")?;
                                value_count = value_count
                                    .checked_add(retired_len)
                                    .context("opaque replica-state value counter overflow")?;
                            }
                            if let Some(retired_range) = pending_retirements[slot_index].take() {
                                if let Some(retirement) = retirement.as_deref_mut() {
                                    retirement.optimizer.retire(retired_range)?;
                                }
                            }
                        }

                        let mut source_commands = vulkan::ComputeBatch::new(&source.device)?;
                        if slot.source_requires_acquire {
                            source_commands.acquire_buffer_from_external(
                                &slot.source_window,
                                slot.capacity_values,
                            )?;
                        }
                        source.optimizer.record_range_copy(
                            &mut source_commands,
                            tensor_index,
                            plane,
                            offset,
                            len,
                            &slot.source_window,
                        )?;
                        let carries_step_metadata =
                            current_range_index == 0 && plane == RwkvReplicaStatePlane::ExpAvgSq;
                        if carries_step_metadata {
                            if step_metadata_source_requires_acquire {
                                source_commands.acquire_buffer_from_external(
                                    &step_metadata_source_window,
                                    step_metadata_words,
                                )?;
                            }
                            source.optimizer.record_step_metadata_pack(
                                &mut source_commands,
                                &step_metadata_source_window,
                            )?;
                            source_commands.release_buffer_to_external(
                                &step_metadata_source_window,
                                step_metadata_words,
                            )?;
                        }
                        source_commands.release_buffer_to_external(
                            &slot.source_window,
                            slot.capacity_values,
                        )?;
                        slot.source_submission = Some(if slot.source_requires_acquire {
                            source_commands.submit_async_wait_signal_raw_binary_semaphores(
                                slot.returned.destination_semaphore(),
                                slot.ready.source_semaphore(),
                            )?
                        } else {
                            source_commands.submit_async_signal_raw_binary_semaphore(
                                slot.ready.source_semaphore(),
                            )?
                        });

                        let mut destination_commands = vulkan::ComputeBatch::new(&self.device)?;
                        destination_commands.acquire_buffer_from_external(
                            &slot.destination_window,
                            slot.capacity_values,
                        )?;
                        if carries_step_metadata {
                            destination_commands.acquire_buffer_from_external(
                                &step_metadata_destination_window,
                                step_metadata_words,
                            )?;
                            self.full_model_optimizer
                                .record_replica_step_metadata_write(
                                    &mut destination_commands,
                                    &source.optimizer,
                                    &step_metadata_destination_window,
                                )?;
                            destination_commands.release_buffer_to_external(
                                &step_metadata_destination_window,
                                step_metadata_words,
                            )?;
                            step_metadata_source_requires_acquire = true;
                        }
                        self.full_model_optimizer.record_replica_state_range_write(
                            &mut destination_commands,
                            &destination_trainables,
                            tensor_index,
                            plane,
                            offset,
                            len,
                            &slot.destination_window,
                        )?;
                        destination_commands.release_buffer_to_external(
                            &slot.destination_window,
                            slot.capacity_values,
                        )?;
                        slot.destination_submission = Some(
                            destination_commands.submit_async_wait_signal_raw_binary_semaphores(
                                slot.ready.destination_semaphore(),
                                slot.returned.source_semaphore(),
                            )?,
                        );
                        slot.source_requires_acquire = true;
                        slot.in_flight_len = Some(len);
                        pending_retirements[slot_index] = (plane
                            == RwkvReplicaStatePlane::ExpAvgSq)
                            .then_some(current_range_index);
                        source_chunk_index = source_chunk_index
                            .checked_add(1)
                            .context("opaque replica-state source chunk counter overflow")?;
                    }
                    state_range_index = state_range_index
                        .checked_add(1)
                        .context("opaque replica-state range counter overflow")?;
                    offset += len;
                }
            }
            // As above, join all remaining plane transfers before publishing
            // the final range retirements to the primary optimizer.
            for slot in transport_slots.iter_mut() {
                if let Some(retired_len) = slot.retire()? {
                    chunk_count = chunk_count
                        .checked_add(1)
                        .context("opaque replica-state chunk counter overflow")?;
                    value_count = value_count
                        .checked_add(retired_len)
                        .context("opaque replica-state value counter overflow")?;
                }
            }
            for retired_range in pending_retirements.iter_mut().filter_map(Option::take) {
                if let Some(retirement) = retirement.as_deref_mut() {
                    retirement.optimizer.retire(retired_range)?;
                }
            }
            if chunk_count != source_chunk_index {
                bail!(
                    "opaque replica-state pipeline retired {chunk_count} chunks after submitting {source_chunk_index}"
                );
            }
            anyhow::ensure!(
                state_range_index == state_range_count,
                "opaque replica-state stream traversed {state_range_index} ranges; expected {state_range_count}"
            );
            let mut refresh = vulkan::ComputeBatch::new(&self.device)?;
            self.full_model_optimizer
                .record_refresh_parameter_mirrors(&mut refresh, &destination_trainables)?;
            refresh.submit()?;
            Ok(())
        })();
        if let Err(err) = transport_result {
            let drain_result = transport_slots
                .iter_mut()
                .try_for_each(|slot| slot.retire().map(|_| ()));
            if let Err(drain_err) = drain_result {
                return Err(err.context(format!(
                    "opaque replica-state transport failed and draining in-flight GPU work also failed: {drain_err:#}"
                )));
            }
            return Err(err.context(
                "opaque replica-state transport failed; destination state may be partial and must not train until resynchronized",
            ));
        }
        drop(destination_trainables);
        drop(destination_registry);
        transport.step_metadata_source_requires_acquire = step_metadata_source_requires_acquire;
        self.finalize_streamed_replica_state_device_step_metadata_from(source)?;
        self.opaque_external_gradient_transports.push(transport);
        Ok(Some(HierarchosReplicaStateStreamStats {
            backend: VulkanGradientTransportBackend::OpaqueExternalMemory,
            tensor_count: layout.len(),
            chunk_count,
            value_count,
            max_chunk_values: chunk_capacity,
            pipeline_slots: CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS,
            persistent_transport_reused,
            peak_host_state_bytes: 0,
            peak_device_state_bytes: transport_capacity
                .checked_mul(std::mem::size_of::<f32>())
                .and_then(|bytes| bytes.checked_mul(2))
                .and_then(|bytes| bytes.checked_mul(CROSS_ADAPTER_GRADIENT_PIPELINE_SLOTS))
                .context("opaque replica-state device-byte count overflow")?,
            queue_submissions: chunk_count
                .checked_mul(2)
                .and_then(|submissions| submissions.checked_add(1))
                .context("opaque replica-state submission count overflow")?,
        }))
    }

    /// Backwards-compatible convenience wrapper for callers that already own a
    /// graph reference. Multi-replica fanout should capture one transport source
    /// and call `stream_full_model_replica_state_from_source` concurrently.
    pub fn stream_full_model_replica_state_from(
        &mut self,
        source: &HierarchosTrainingGraph,
        max_chunk_values: usize,
    ) -> Result<Option<HierarchosReplicaStateStreamStats>> {
        let source = source.full_model_replica_transport_source()?;
        self.stream_full_model_replica_state_from_source(&source, max_chunk_values)
    }

    /// Read every parameter represented by the canonical full-model optimizer
    /// from device memory. A frontend-enabled graph returns the historical
    /// recurrent/projection/output registry plus all learned coherent-v9
    /// token/memory tensors; the tied `lm_head.weight` appears exactly once.
    pub fn full_model_parameter_snapshots(&self) -> Result<Vec<RwkvParameterSnapshot>> {
        let registry = full_model_named_trainables(
            &self.h_recurrent,
            &self.l_recurrent,
            &self.projections,
            self.token_frontend.as_ref(),
            &self.output,
        )?;
        let trainables = registry
            .iter()
            .map(NamedTrainable::as_trainable)
            .collect::<Vec<_>>();
        let mut commands = vulkan::ComputeBatch::new(&self.device)?;
        self.full_model_optimizer
            .record_parameter_readback(&mut commands, &trainables)?;
        commands.submit()?;
        self.full_model_optimizer.read_parameter_snapshots()
    }

    /// Capture the synchronized state needed to clone a completed optimizer
    /// boundary onto another Vulkan adapter. Open gradient windows are excluded
    /// deliberately; those move through `HierarchosPendingGradientShard`.
    pub fn full_model_replica_state(&self) -> Result<HierarchosFullModelReplicaState> {
        if self.full_model_accumulation_open {
            bail!("cannot snapshot a closed-step replica state while accumulation is open");
        }
        if self.ltm_alignment_controller.sampled_rows_in_window != 0
            || self
                .ltm_alignment_controller
                .sampled_rows_in_controller_microbatch
                != 0
        {
            bail!("closed full-model replica state has live LTM accumulation counters");
        }
        Ok(HierarchosFullModelReplicaState {
            architecture_revision: self.config.architecture_revision.clone(),
            training_precision_policy: self.training_precision_policy.label().to_string(),
            parameters: self.full_model_parameter_snapshots()?,
            optimizer: self.full_model_optimizer_state()?,
            training_step: self.training_step(),
            ltm_alignment_controller: self.ltm_alignment_controller.clone(),
        })
    }

    /// Replace this closed graph with a primary replica's canonical parameter,
    /// AdamW, curriculum, and LTM-controller state. Compact mixed-precision
    /// mirrors are regenerated locally from the incoming FP32 masters.
    pub fn load_full_model_replica_state(
        &mut self,
        state: &HierarchosFullModelReplicaState,
    ) -> Result<()> {
        if self.full_model_accumulation_open {
            bail!("cannot load a full-model replica state into an open accumulation window");
        }
        if state.architecture_revision != self.config.architecture_revision {
            bail!(
                "replica architecture {:?} does not match destination {:?}",
                state.architecture_revision,
                self.config.architecture_revision
            );
        }
        if state.training_precision_policy != self.training_precision_policy.label() {
            bail!(
                "replica precision {:?} does not match destination {:?}",
                state.training_precision_policy,
                self.training_precision_policy.label()
            );
        }
        state.ltm_alignment_controller.validate_policy()?;
        if state.ltm_alignment_controller.sampled_rows_in_window != 0
            || state
                .ltm_alignment_controller
                .sampled_rows_in_controller_microbatch
                != 0
        {
            bail!("closed replica state cannot carry live LTM accumulation counters");
        }
        let active_policy = &self.ltm_alignment_controller;
        if state.ltm_alignment_controller.weight != active_policy.weight
            || state.ltm_alignment_controller.stride != active_policy.stride
            || state.ltm_alignment_controller.min_updates != active_policy.min_updates
            || state.ltm_alignment_controller.ready_threshold != active_policy.ready_threshold
            || state.ltm_alignment_controller.ema_decay != active_policy.ema_decay
            || state.ltm_alignment_controller.writer_max_norm != active_policy.writer_max_norm
        {
            bail!("replica LTM alignment policy does not match the active model package");
        }
        {
            let Self {
                h_recurrent,
                l_recurrent,
                projections,
                token_frontend,
                output,
                full_model_optimizer,
                ..
            } = self;
            let registry = full_model_named_trainables(
                h_recurrent,
                l_recurrent,
                projections,
                token_frontend.as_ref(),
                output,
            )?;
            let trainables = registry
                .iter()
                .map(NamedTrainable::as_trainable)
                .collect::<Vec<_>>();
            full_model_optimizer.load_parameter_snapshots(&trainables, &state.parameters)?;
            full_model_optimizer.load_state(&state.optimizer)?;
        }
        match (self.token_frontend.is_some(), state.training_step) {
            (true, Some(step)) => self.set_training_step(step)?,
            (true, None) => bail!("frontend-enabled replica state is missing training_step"),
            (false, Some(_)) => {
                bail!("frontend-disabled replica state unexpectedly carries training_step")
            }
            (false, None) => {}
        }
        self.ltm_alignment_controller = state.ltm_alignment_controller.clone();
        self.ltm_alignment_device_control
            .invalidate_device_authority();
        self.sync_ltm_alignment_config();
        self.full_model_accumulation_normalization = None;
        self.full_model_direct_lm_gradient = None;
        self.val_proj_active_in_window = false;
        self.ltm_alignment_pytorch_tbptt_weighting_in_window = None;
        self.ltm_alignment_readback_pending = false;
        self.output
            .finalize_external_optimizer_step(state.optimizer.step);
        Ok(())
    }

    /// Export current Vulkan-trained tensors back into an ordinary Hierarchos
    /// SafeTensors model package. Every untouched tensor and the source metadata
    /// are preserved, so the result remains directly loadable by PyTorch and by
    /// the native Rust/CUDA inference paths. A frontend-enabled graph also
    /// persists the explicit memory-gate curriculum position.
    pub fn save_full_model_checkpoint(
        &self,
        source_model: impl AsRef<Path>,
        destination_model: impl AsRef<Path>,
    ) -> Result<()> {
        let snapshots = self.full_model_parameter_snapshots()?;
        let mut replacements = snapshots
            .iter()
            .map(|snapshot| (snapshot.name.as_str(), snapshot.values.as_slice()))
            .collect::<Vec<_>>();
        let warmup_step = self
            .token_frontend
            .as_ref()
            .map(HierarchosTokenFrontendOp::memory_gate_warmup_step_value);
        let warmup_storage = warmup_step.map(|value| [value]);
        if let Some(values) = warmup_storage.as_ref() {
            replacements.push(("memory_gate_warmup_step", values.as_slice()));
        }
        replace_f32_tensor_values(
            source_model.as_ref(),
            destination_model.as_ref(),
            &replacements,
        )
    }

    pub fn save_full_model_optimizer_checkpoint(&self, path: impl AsRef<Path>) -> Result<()> {
        write_adamw_optimizer_state(path.as_ref(), &self.full_model_optimizer_state()?)
    }

    pub fn load_full_model_optimizer_checkpoint(&mut self, path: impl AsRef<Path>) -> Result<()> {
        let state = read_adamw_optimizer_state(path.as_ref())?;
        self.full_model_optimizer.load_state(&state)
    }

    /// Export a complete inference-compatible model directory plus the portable
    /// AdamW companion needed to resume training. The ordinary model package is
    /// intentionally kept free of optimizer-only tensors, so PyTorch CPU/CUDA
    /// and `hierarchos-inference` can load `model.safetensors` unchanged.
    pub fn export_training_checkpoint_package(
        &self,
        source_model_dir: impl AsRef<Path>,
        output_dir: impl AsRef<Path>,
    ) -> Result<HierarchosTrainingCheckpointManifest> {
        if self.ltm_alignment_device_control.host_metadata_stale() {
            bail!(
                "training checkpoint export requires synchronized device-resident LTM readiness metadata; call synchronize_ltm_alignment_controller_metadata (or synchronize_dynamic_loss_scaling_metadata) first"
            );
        }
        let source_model_dir = source_model_dir.as_ref();
        let output_dir = output_dir.as_ref();
        if source_model_dir == output_dir {
            bail!("training checkpoint export requires a distinct output directory");
        }
        let config = ModelConfig::from_model_dir(source_model_dir)
            .context("validating source model package for training checkpoint export")?;
        if config.architecture_revision != self.config.architecture_revision
            || config.context_dim != self.config.context_dim
            || config.vocab_size != self.config.vocab_size
        {
            bail!(
                "source model package does not match the active Vulkan graph: architecture/context/vocab={:?}/{}/{} vs {:?}/{}/{}",
                config.architecture_revision,
                config.context_dim,
                config.vocab_size,
                self.config.architecture_revision,
                self.config.context_dim,
                self.config.vocab_size,
            );
        }

        std::fs::create_dir_all(output_dir).with_context(|| {
            format!(
                "creating training checkpoint package {}",
                output_dir.display()
            )
        })?;
        for stale_name in [
            HIERARCHOS_VULKAN_PORTABLE_REPLAY_FILENAME,
            HIERARCHOS_VULKAN_PORTABLE_REPLAY_TENSOR_FILENAME,
        ] {
            let stale_path = output_dir.join(stale_name);
            if stale_path.exists() {
                std::fs::remove_file(&stale_path)
                    .with_context(|| format!("removing stale {}", stale_path.display()))?;
            }
        }
        for entry in std::fs::read_dir(source_model_dir).with_context(|| {
            format!(
                "reading source model package {}",
                source_model_dir.display()
            )
        })? {
            let entry = entry?;
            let path = entry.path();
            if path.is_file()
                && path.file_name().and_then(|name| name.to_str()) != Some("model.safetensors")
                && path.file_name().and_then(|name| name.to_str())
                    != Some(HIERARCHOS_VULKAN_OPTIMIZER_FILENAME)
                && path.file_name().and_then(|name| name.to_str())
                    != Some(HIERARCHOS_VULKAN_GRADIENTS_FILENAME)
                && path.file_name().and_then(|name| name.to_str())
                    != Some(HIERARCHOS_VULKAN_TRAINING_MANIFEST_FILENAME)
                && path.file_name().and_then(|name| name.to_str())
                    != Some(HIERARCHOS_VULKAN_PORTABLE_REPLAY_FILENAME)
                && path.file_name().and_then(|name| name.to_str())
                    != Some(HIERARCHOS_VULKAN_PORTABLE_REPLAY_TENSOR_FILENAME)
            {
                std::fs::copy(&path, output_dir.join(entry.file_name())).with_context(|| {
                    format!(
                        "copying model-package member {} into {}",
                        path.display(),
                        output_dir.display()
                    )
                })?;
            }
        }

        self.save_full_model_checkpoint(
            source_model_dir.join("model.safetensors"),
            output_dir.join("model.safetensors"),
        )?;
        for config_name in [
            "hierarchos_rust_config.json",
            "hierarchos_config.json",
            "config.json",
        ] {
            self.write_ltm_alignment_config_state(&output_dir.join(config_name))?;
        }
        let optimizer_state = self.full_model_optimizer_state()?;
        write_adamw_optimizer_state(
            &output_dir.join(HIERARCHOS_VULKAN_OPTIMIZER_FILENAME),
            &optimizer_state,
        )?;
        let optimizer_slot_names = optimizer_state
            .slots
            .iter()
            .map(|slot| slot.name.as_str())
            .collect::<Vec<_>>();
        validate_f32_tensor_names(&output_dir.join("model.safetensors"), &optimizer_slot_names)?;
        let accumulation = if self.full_model_accumulation_open {
            Some(
                self.full_model_accumulation_normalization
                    .context("open Vulkan accumulation window is missing normalization state")?,
            )
        } else {
            None
        };
        let direct_lm_gradient =
            if self.full_model_accumulation_open {
                Some(self.full_model_direct_lm_gradient.context(
                    "open Vulkan accumulation window is missing lm_head gradient topology",
                )?)
            } else {
                None
            };
        let mut val_proj_gradient_weight_applied = false;
        let gradient_state = if self.full_model_accumulation_open {
            let override_gradient = direct_lm_gradient.filter(|direct| *direct).map(|_| {
                (
                    LM_HEAD_WEIGHT_TENSOR_NAME,
                    self.shared_lm_head.gradient_buffer(),
                )
            });
            let mut state = self
                .full_model_optimizer
                .gradient_state_snapshot_with_override(override_gradient)?;
            if self.val_proj_active_in_window
                && self.ltm_alignment_pytorch_tbptt_weighting_in_window == Some(true)
            {
                let weight = self.ltm_alignment_controller.weight;
                if !weight.is_finite() || weight <= 0.0 {
                    bail!(
                        "active PyTorch-TBPTT val_proj checkpoint requires a finite positive LTM alignment weight; got {weight}"
                    );
                }
                let val_proj = state
                    .iter_mut()
                    .find(|snapshot| snapshot.name == VAL_PROJ_WEIGHT_TENSOR_NAME)
                    .context("pending gradient registry is missing val_proj.weight")?;
                for value in &mut val_proj.values {
                    *value *= weight;
                    if !value.is_finite() {
                        bail!(
                            "canonical val_proj.weight pending gradient became non-finite while applying LTM objective weight"
                        );
                    }
                }
                val_proj_gradient_weight_applied = true;
            }
            write_pending_gradient_state(
                &output_dir.join(HIERARCHOS_VULKAN_GRADIENTS_FILENAME),
                &state,
            )?;
            Some(state)
        } else {
            let stale_gradient_path = output_dir.join(HIERARCHOS_VULKAN_GRADIENTS_FILENAME);
            if stale_gradient_path.exists() {
                std::fs::remove_file(&stale_gradient_path)
                    .with_context(|| format!("removing stale {}", stale_gradient_path.display()))?;
            }
            None
        };
        let manifest = HierarchosTrainingCheckpointManifest {
            format: HIERARCHOS_VULKAN_TRAINING_MANIFEST_FORMAT.to_string(),
            architecture_revision: self.config.architecture_revision.clone(),
            model_file: "model.safetensors".to_string(),
            optimizer_file: HIERARCHOS_VULKAN_OPTIMIZER_FILENAME.to_string(),
            optimizer_step: optimizer_state.step,
            optimizer_tensor_count: optimizer_state.slots.len(),
            training_step: self.training_step(),
            training_precision_policy: self.training_precision_policy.label().to_string(),
            parameter_state: Some(HierarchosParameterStateContract::portable(
                "model.safetensors",
            )),
            completed_epoch: None,
            mid_epoch_step: None,
            training_session: None,
            portable_replay_file: None,
            portable_replay_tensor_file: None,
            ltm_alignment_controller: Some(self.ltm_alignment_controller.clone()),
            gradient_file: gradient_state
                .as_ref()
                .map(|_| HIERARCHOS_VULKAN_GRADIENTS_FILENAME.to_string()),
            gradient_tensor_count: gradient_state.as_ref().map_or(0, Vec::len),
            accumulation_open: self.full_model_accumulation_open,
            accumulation_normalization: accumulation
                .map(|state| state.normalization.checkpoint_label().to_string()),
            accumulation_consumed_token_count: accumulation
                .map_or(0, |state| state.consumed_token_count as u64),
            accumulation_consumed_supervision_mass: accumulation
                .and_then(|state| state.consumed_supervision_mass),
            accumulation_target_token_count: accumulation
                .and_then(|state| state.target_token_count)
                .map(|value| value as u64),
            accumulation_target_supervision_mass: accumulation
                .and_then(|state| state.target_supervision_mass),
            lm_head_gradient_topology: direct_lm_gradient.map(|direct| {
                if direct {
                    "shared-tied".to_string()
                } else {
                    "optimizer-registry".to_string()
                }
            }),
            val_proj_active_in_window: self.full_model_accumulation_open
                && self.val_proj_active_in_window,
            val_proj_gradient_weight_applied,
            ltm_alignment_pytorch_tbptt_weighting_in_window: self
                .full_model_accumulation_open
                .then_some(self.ltm_alignment_pytorch_tbptt_weighting_in_window)
                .flatten(),
        };
        let manifest_bytes = serde_json::to_vec_pretty(&manifest)
            .context("serializing Vulkan training checkpoint manifest")?;
        std::fs::write(
            output_dir.join(HIERARCHOS_VULKAN_TRAINING_MANIFEST_FILENAME),
            manifest_bytes,
        )
        .with_context(|| format!("writing training manifest in {}", output_dir.display()))?;
        Ok(manifest)
    }

    /// Export a complete v4 training checkpoint, its typed backend-neutral
    /// training session (when supplied), and the host replay sidecar in the same
    /// native operation. The resulting package can move from Vulkan training
    /// into PyTorch CPU/CUDA resume without serializing scheduler policy as a
    /// PyTorch checkpoint object or requiring an out-of-band mutation step.
    pub fn export_training_checkpoint_package_with_replay(
        &self,
        source_model_dir: impl AsRef<Path>,
        output_dir: impl AsRef<Path>,
        replay: &HierarchosPortableTrainingReplay,
    ) -> Result<HierarchosTrainingCheckpointManifest> {
        replay.validate()?;
        let output_dir = output_dir.as_ref();
        let mut manifest = self.export_training_checkpoint_package(source_model_dir, output_dir)?;
        let mut training_session = replay.training_session.clone();

        // The portable gradient companion is a backend-neutral FP32 numerator,
        // not a snapshot of a backend's transient GradScaler domain. Native
        // dynamic loss scaling intentionally leaves the live Vulkan registry
        // source-scaled until the optimizer boundary, so canonicalize a copy on
        // disk while leaving the live accumulation window untouched. A later
        // Vulkan destination can re-enter the saved scaler domain explicitly;
        // PyTorch/CUDA can consume the canonical gradients directly.
        if let Some(session) = training_session.as_mut() {
            if let Some(policy) = session.execution_policy.as_mut() {
                let loss_scaling = &mut policy.loss_scaling;
                if loss_scaling.pending_gradients_scaled {
                    if !manifest.accumulation_open {
                        bail!(
                            "portable replay cannot mark pending gradients scaled at a closed optimizer boundary"
                        );
                    }
                    let source_scale = loss_scaling.backward_source_scale()?;
                    let gradient_file = manifest
                        .gradient_file
                        .as_deref()
                        .context("scaled open checkpoint is missing gradient_file")?;
                    let gradient_path = output_dir.join(gradient_file);
                    let mut gradient_state = read_pending_gradient_state(&gradient_path)?;
                    let reciprocal = 1.0 / source_scale;
                    for snapshot in &mut gradient_state {
                        for value in &mut snapshot.values {
                            *value *= reciprocal;
                            if !value.is_finite() {
                                bail!(
                                    "portable pending gradient {:?} became non-finite while removing dynamic loss scale",
                                    snapshot.name
                                );
                            }
                        }
                    }
                    write_pending_gradient_state(&gradient_path, &gradient_state)?;
                    loss_scaling.pending_gradients_scaled = false;
                }
            }
        }

        let replay_document = serde_json::json!({
            "format": HIERARCHOS_VULKAN_PORTABLE_REPLAY_FORMAT,
            "state": replay.encoded_state,
        });
        let replay_path = output_dir.join(HIERARCHOS_VULKAN_PORTABLE_REPLAY_FILENAME);
        std::fs::write(
            &replay_path,
            serde_json::to_vec(&replay_document)
                .context("serializing Vulkan portable replay document")?,
        )
        .with_context(|| format!("writing {}", replay_path.display()))?;

        let replay_tensor_member = if replay.tensors.is_empty() {
            None
        } else {
            let tensor_path = output_dir.join(HIERARCHOS_VULKAN_PORTABLE_REPLAY_TENSOR_FILENAME);
            write_portable_replay_tensors(
                &tensor_path,
                HIERARCHOS_VULKAN_PORTABLE_REPLAY_FORMAT,
                &replay.tensors,
            )?;
            Some(HIERARCHOS_VULKAN_PORTABLE_REPLAY_TENSOR_FILENAME.to_string())
        };

        manifest.format = HIERARCHOS_VULKAN_TRAINING_MANIFEST_FORMAT.to_string();
        manifest.completed_epoch = Some(replay.completed_epoch);
        manifest.mid_epoch_step = Some(replay.mid_epoch_step);
        manifest.training_session = training_session;
        manifest.portable_replay_file =
            Some(HIERARCHOS_VULKAN_PORTABLE_REPLAY_FILENAME.to_string());
        manifest.portable_replay_tensor_file = replay_tensor_member;
        let manifest_path = output_dir.join(HIERARCHOS_VULKAN_TRAINING_MANIFEST_FILENAME);
        std::fs::write(
            &manifest_path,
            serde_json::to_vec_pretty(&manifest)
                .context("serializing Vulkan training checkpoint replay manifest")?,
        )
        .with_context(|| format!("writing {}", manifest_path.display()))?;
        Ok(manifest)
    }

    /// Restore the training-only state from a package that was constructed with
    /// `export_training_checkpoint_package`. The graph itself should be created
    /// from this package first so its model weights are already the exported
    /// masters; this method restores AdamW moments and the explicit curriculum
    /// step without constraining the execution precision arm.
    pub fn load_training_checkpoint_package_state(
        &mut self,
        package_dir: impl AsRef<Path>,
    ) -> Result<HierarchosTrainingCheckpointManifest> {
        let package_dir = package_dir.as_ref();
        let manifest_path = package_dir.join(HIERARCHOS_VULKAN_TRAINING_MANIFEST_FILENAME);
        let manifest: HierarchosTrainingCheckpointManifest = serde_json::from_slice(
            &std::fs::read(&manifest_path)
                .with_context(|| format!("reading {}", manifest_path.display()))?,
        )
        .with_context(|| format!("decoding {}", manifest_path.display()))?;
        if manifest.format != HIERARCHOS_VULKAN_TRAINING_MANIFEST_FORMAT
            && manifest.format != HIERARCHOS_VULKAN_TRAINING_MANIFEST_FORMAT_V5
            && manifest.format != HIERARCHOS_VULKAN_TRAINING_MANIFEST_FORMAT_V4
            && manifest.format != HIERARCHOS_VULKAN_TRAINING_MANIFEST_FORMAT_V3
            && manifest.format != HIERARCHOS_VULKAN_TRAINING_MANIFEST_FORMAT_V2
            && manifest.format != HIERARCHOS_VULKAN_TRAINING_MANIFEST_FORMAT_V1
        {
            bail!(
                "unsupported Vulkan training checkpoint manifest format {:?}",
                manifest.format
            );
        }
        if let Some(training_session) = manifest.training_session.as_ref() {
            training_session.validate()?;
            if manifest
                .completed_epoch
                .is_some_and(|epoch| epoch != training_session.completed_epoch)
                || manifest
                    .mid_epoch_step
                    .is_some_and(|step| step != training_session.mid_epoch_step)
            {
                bail!(
                    "training checkpoint top-level cursor disagrees with native training session"
                );
            }
        }
        validate_portable_checkpoint_gradient_domain(
            &manifest.format,
            manifest.training_session.as_ref(),
        )?;
        if manifest.architecture_revision != self.config.architecture_revision {
            bail!(
                "training checkpoint architecture {:?} does not match active graph {:?}",
                manifest.architecture_revision,
                self.config.architecture_revision
            );
        }
        if Path::new(&manifest.model_file).components().count() != 1 {
            bail!("training checkpoint model_file must be a package-local filename");
        }
        match manifest.parameter_state.as_ref() {
            Some(parameter_state) => {
                parameter_state.validate(&manifest.model_file)?;
                if manifest.format == HIERARCHOS_VULKAN_TRAINING_MANIFEST_FORMAT
                    && parameter_state.format != HIERARCHOS_VULKAN_PARAMETER_STATE_FORMAT
                {
                    bail!(
                        "v6 Vulkan training checkpoint requires portable parameter-state v2 alias topology"
                    );
                }
            }
            None if manifest.format == HIERARCHOS_VULKAN_TRAINING_MANIFEST_FORMAT
                || manifest.format == HIERARCHOS_VULKAN_TRAINING_MANIFEST_FORMAT_V5 =>
            {
                bail!("v5+ Vulkan training checkpoint is missing portable parameter_state")
            }
            None => {}
        }
        if Path::new(&manifest.optimizer_file).components().count() != 1 {
            bail!("training checkpoint optimizer_file must be a package-local filename");
        }
        let optimizer_state =
            read_adamw_optimizer_state(&package_dir.join(&manifest.optimizer_file))?;
        if optimizer_state.step != manifest.optimizer_step
            || optimizer_state.slots.len() != manifest.optimizer_tensor_count
        {
            bail!(
                "training manifest optimizer summary step/tensors={}/{} does not match companion checkpoint {}/{}",
                manifest.optimizer_step,
                manifest.optimizer_tensor_count,
                optimizer_state.step,
                optimizer_state.slots.len()
            );
        }
        if manifest.parameter_state.is_some() {
            let optimizer_slot_names = optimizer_state
                .slots
                .iter()
                .map(|slot| slot.name.as_str())
                .collect::<Vec<_>>();
            validate_f32_tensor_names(
                &package_dir.join(&manifest.model_file),
                &optimizer_slot_names,
            )?;
        }
        self.full_model_optimizer.load_state(&optimizer_state)?;
        if let Some(step) = manifest.training_step {
            self.set_training_step(step)?;
        }
        if let Some(saved_controller) = manifest.ltm_alignment_controller.as_ref() {
            saved_controller.validate_policy()?;
            if !manifest.accumulation_open
                && (saved_controller.sampled_rows_in_window != 0
                    || saved_controller.sampled_rows_in_controller_microbatch != 0)
            {
                bail!("training checkpoint has LTM accumulation counters without an open gradient window");
            }
            let active_policy = &self.ltm_alignment_controller;
            if saved_controller.weight != active_policy.weight
                || saved_controller.stride != active_policy.stride
                || saved_controller.min_updates != active_policy.min_updates
                || saved_controller.ready_threshold != active_policy.ready_threshold
                || saved_controller.ema_decay != active_policy.ema_decay
                || saved_controller.writer_max_norm != active_policy.writer_max_norm
            {
                bail!(
                    "training checkpoint LTM alignment policy does not match the active model package"
                );
            }
            self.ltm_alignment_controller = saved_controller.clone();
            self.ltm_alignment_device_control
                .invalidate_device_authority();
            self.val_proj_active_in_window =
                manifest.accumulation_open && manifest.val_proj_active_in_window;
            self.ltm_alignment_readback_pending = false;
            self.sync_ltm_alignment_config();
        }
        if manifest.accumulation_open {
            if manifest.format == HIERARCHOS_VULKAN_TRAINING_MANIFEST_FORMAT_V1 {
                bail!("v1 Vulkan training checkpoints cannot contain an open accumulation window");
            }
            let gradient_file = manifest
                .gradient_file
                .as_deref()
                .context("open training checkpoint is missing gradient_file")?;
            if Path::new(gradient_file).components().count() != 1 {
                bail!("training checkpoint gradient_file must be a package-local filename");
            }
            let mut gradient_state = read_pending_gradient_state(&package_dir.join(gradient_file))?;
            if gradient_state.len() != manifest.gradient_tensor_count {
                bail!(
                    "training manifest pending-gradient tensor count {} does not match companion checkpoint {}",
                    manifest.gradient_tensor_count,
                    gradient_state.len()
                );
            }
            let normalization = HierarchosSequenceGradientNormalization::from_checkpoint_label(
                manifest
                    .accumulation_normalization
                    .as_deref()
                    .context("open training checkpoint is missing accumulation_normalization")?,
            )?;
            let consumed_token_count = usize::try_from(manifest.accumulation_consumed_token_count)
                .context("checkpoint accumulation consumed token count does not fit usize")?;
            if consumed_token_count == 0 {
                bail!("open training checkpoint has zero consumed accumulation tokens");
            }
            let target_token_count = manifest
                .accumulation_target_token_count
                .map(usize::try_from)
                .transpose()
                .context("checkpoint accumulation target token count does not fit usize")?;
            if let Some(target) = target_token_count {
                if target < consumed_token_count {
                    bail!(
                        "checkpoint accumulation target token count {target} is smaller than consumed count {consumed_token_count}"
                    );
                }
            }
            let (consumed_supervision_mass, target_supervision_mass) = match normalization {
                HierarchosSequenceGradientNormalization::MeanBySupervisionWeight => {
                    let consumed = manifest.accumulation_consumed_supervision_mass.context(
                        "weighted-token checkpoint is missing consumed supervision mass",
                    )?;
                    if !consumed.is_finite() || consumed <= 0.0 {
                        bail!(
                            "weighted-token checkpoint consumed supervision mass must be finite and positive; got {consumed}"
                        );
                    }
                    if let Some(target) = manifest.accumulation_target_supervision_mass {
                        if !target.is_finite() || target <= 0.0 {
                            bail!(
                                "weighted-token checkpoint target supervision mass must be finite and positive; got {target}"
                            );
                        }
                        let tolerance =
                            8.0 * f32::EPSILON * target.abs().max(consumed.abs()).max(1.0);
                        if target + tolerance < consumed {
                            bail!(
                                "weighted-token checkpoint target supervision mass {target} is smaller than consumed mass {consumed}"
                            );
                        }
                    }
                    (
                        Some(consumed),
                        manifest.accumulation_target_supervision_mass,
                    )
                }
                _ => (None, None),
            };
            if let Some(topology) = manifest.lm_head_gradient_topology.as_deref() {
                if topology != "shared-tied" && topology != "optimizer-registry" {
                    bail!("unsupported checkpoint lm_head gradient topology {topology:?}");
                }
            }
            if manifest.val_proj_gradient_weight_applied {
                if !manifest.val_proj_active_in_window
                    || manifest.ltm_alignment_pytorch_tbptt_weighting_in_window != Some(true)
                {
                    bail!(
                        "canonical val_proj pending-gradient weight requires an active PyTorch-TBPTT LTM alignment window"
                    );
                }
                let weight = self.ltm_alignment_controller.weight;
                if !weight.is_finite() || weight <= 0.0 {
                    bail!(
                        "canonical val_proj pending-gradient restore requires a finite positive LTM alignment weight; got {weight}"
                    );
                }
                let val_proj = gradient_state
                    .iter_mut()
                    .find(|snapshot| snapshot.name == VAL_PROJ_WEIGHT_TENSOR_NAME)
                    .context("canonical pending gradient registry is missing val_proj.weight")?;
                for value in &mut val_proj.values {
                    *value /= weight;
                    if !value.is_finite() {
                        bail!(
                            "internal val_proj.weight pending gradient became non-finite while removing portable LTM objective weight"
                        );
                    }
                }
            }
            // The pending-gradient file is canonical by parameter name, so a
            // checkpoint can cross the direct tied-gradient/staged-registry
            // execution boundary without changing its mathematical state.
            let active_direct_lm_gradient =
                std::env::var_os(HIERARCHOS_VULKAN_LM_FORCE_CANONICAL_GRAD_STAGING_ENV).is_none();
            let override_gradient = active_direct_lm_gradient.then_some((
                LM_HEAD_WEIGHT_TENSOR_NAME,
                self.shared_lm_head.gradient_buffer(),
            ));
            self.full_model_optimizer
                .load_gradient_state_with_override(&gradient_state, override_gradient)?;
            self.full_model_accumulation_normalization =
                Some(FullModelAccumulationNormalizationState {
                    normalization,
                    consumed_token_count,
                    consumed_supervision_mass,
                    target_token_count,
                    target_supervision_mass,
                });
            self.full_model_direct_lm_gradient = Some(active_direct_lm_gradient);
            self.full_model_accumulation_open = true;
            self.ltm_alignment_pytorch_tbptt_weighting_in_window =
                manifest.ltm_alignment_pytorch_tbptt_weighting_in_window;
        } else {
            if manifest.gradient_file.is_some() || manifest.gradient_tensor_count != 0 {
                bail!("closed training checkpoint unexpectedly declares pending gradients");
            }
            if manifest.val_proj_gradient_weight_applied {
                bail!("closed training checkpoint cannot declare a weighted pending val_proj gradient");
            }
            self.full_model_accumulation_open = false;
            self.full_model_accumulation_normalization = None;
            self.full_model_direct_lm_gradient = None;
            self.val_proj_active_in_window = false;
            self.ltm_alignment_pytorch_tbptt_weighting_in_window = None;
        }
        Ok(manifest)
    }

    /// Re-enter the transient dynamic-loss-scaling domain after restoring a
    /// portable open-window checkpoint.
    ///
    /// Portable replay packages store pending gradients as canonical unscaled
    /// FP32 numerators. Before another source-scaled microbatch is accumulated,
    /// Vulkan multiplies the restored registry by the saved scaler value so the
    /// old and new contributions share one domain. The subsequent dynamic
    /// finisher performs the usual single reciprocal unscale over the complete
    /// window. The operation changes gradients only; parameters and AdamW state
    /// remain untouched.
    pub fn rehydrate_full_model_accumulation_for_dynamic_loss_scaling(
        &mut self,
        loss_scaling: &mut HierarchosLossScalingState,
    ) -> Result<u32> {
        if !self.full_model_accumulation_open {
            bail!("dynamic loss-scale rehydration requires an open full-model accumulation window");
        }
        if loss_scaling.mode != "dynamic" {
            bail!("dynamic loss-scale rehydration requires loss_scaling mode=\"dynamic\"");
        }
        if loss_scaling.pending_gradients_scaled {
            return Ok(0);
        }
        let source_scale = loss_scaling.backward_source_scale()?;
        let mut commands = vulkan::ComputeBatch::new(&self.device)?;
        if self.full_model_direct_lm_gradient == Some(true) {
            self.full_model_optimizer
                .record_scale_gradients_with_named_override(
                    &mut commands,
                    source_scale,
                    LM_HEAD_WEIGHT_TENSOR_NAME,
                    self.shared_lm_head.gradient_buffer(),
                )?;
        } else {
            self.full_model_optimizer
                .record_scale_gradients(&mut commands, source_scale)?;
        }
        commands.submit()?;
        loss_scaling.pending_gradients_scaled = true;
        Ok(1)
    }

    /// Scan the canonical pending full-model gradient window that the next
    /// AdamW update would consume. When the tied LM gradient is using its
    /// direct shared-buffer topology, that buffer replaces the optimizer slot
    /// in the scan so the overflow decision follows the exact live step path.
    pub fn pending_full_model_gradients_have_nonfinite(&self) -> Result<bool> {
        if !self.full_model_accumulation_open {
            bail!("full-model gradient overflow detection requires an open accumulation window");
        }
        if self.full_model_direct_lm_gradient == Some(true) {
            self.full_model_optimizer
                .accumulated_gradients_have_nonfinite_with_named_override(
                    LM_HEAD_WEIGHT_TENSOR_NAME,
                    self.shared_lm_head.gradient_buffer(),
                )
        } else {
            self.full_model_optimizer
                .accumulated_gradients_have_nonfinite()
        }
    }

    fn record_full_model_optimizer_finish(
        &mut self,
        commands: &mut vulkan::ComputeBatch,
        hyper: AdamWHyperParams,
        gradient_normalization_scale: f32,
        loss_unscale_factor: f32,
        direct_lm_optimizer_gradient: bool,
    ) -> Result<RwkvOptimizerStepResult> {
        if !gradient_normalization_scale.is_finite() || gradient_normalization_scale <= 0.0 {
            bail!(
                "full-model optimizer normalization scale must be finite and positive; got {gradient_normalization_scale}"
            );
        }
        if !loss_unscale_factor.is_finite() || loss_unscale_factor <= 0.0 {
            bail!(
                "full-model optimizer loss-unscale factor must be finite and positive; got {loss_unscale_factor}"
            );
        }
        let gradient_scale_before_step = gradient_normalization_scale * loss_unscale_factor;
        if !gradient_scale_before_step.is_finite() || gradient_scale_before_step <= 0.0 {
            bail!(
                "full-model optimizer combined gradient scale must be finite and positive; got {gradient_scale_before_step}"
            );
        }
        let val_proj_active = self.val_proj_active_in_window;
        let native_alignment_enabled =
            self.token_frontend.is_some() && self.ltm_alignment_controller.enabled();
        let native_sampled_rows = self.ltm_alignment_controller.sampled_rows_in_window;
        let pytorch_tbptt_ltm_weighting = self.ltm_alignment_pytorch_tbptt_weighting_in_window;
        let alignment_weight = self.ltm_alignment_controller.weight;
        let Self {
            h_recurrent,
            l_recurrent,
            projections,
            token_frontend,
            output,
            full_model_optimizer,
            ..
        } = self;
        let registry = full_model_named_trainables(
            h_recurrent,
            l_recurrent,
            projections,
            token_frontend.as_ref(),
            output,
        )?;
        let trainables = registry
            .iter()
            .map(NamedTrainable::as_trainable)
            .collect::<Vec<_>>();
        let mut inactive_names = Vec::with_capacity(1);
        if token_frontend.is_some() && !val_proj_active {
            inactive_names.push(VAL_PROJ_WEIGHT_TENSOR_NAME);
        }
        if direct_lm_optimizer_gradient {
            let lm_gradient = trainables
                .iter()
                .find(|trainable| trainable.name == LM_HEAD_WEIGHT_TENSOR_NAME)
                .map(|trainable| trainable.gradient)
                .context("full-model registry is missing lm_head.weight gradient override")?;
            full_model_optimizer.record_scale_gradients_with_named_override(
                commands,
                gradient_scale_before_step,
                LM_HEAD_WEIGHT_TENSOR_NAME,
                lm_gradient,
            )?;
            if native_alignment_enabled && val_proj_active {
                if native_sampled_rows == 0 {
                    bail!("active native val_proj window has zero sampled rows");
                }
                let exact_pytorch_tbptt = pytorch_tbptt_ltm_weighting
                    .context("active native val_proj window has no sampled-weighting mode")?;
                let val_proj_scale = if exact_pytorch_tbptt {
                    alignment_weight
                } else {
                    // The native val_proj objective has its own sampled-row
                    // normalization. Cancel only the ordinary sequence/window
                    // normalization here; retain loss_unscale_factor so AMP
                    // scaling is removed from this gradient too.
                    alignment_weight / native_sampled_rows as f32 / gradient_normalization_scale
                };
                full_model_optimizer.record_scale_named_gradient(
                    commands,
                    VAL_PROJ_WEIGHT_TENSOR_NAME,
                    val_proj_scale,
                )?;
            }
            full_model_optimizer.record_step_with_named_gradient_override_and_inactive_names(
                commands,
                &trainables,
                hyper,
                LM_HEAD_WEIGHT_TENSOR_NAME,
                lm_gradient,
                &inactive_names,
            )
        } else {
            full_model_optimizer.record_scale_gradients(commands, gradient_scale_before_step)?;
            if native_alignment_enabled && val_proj_active {
                if native_sampled_rows == 0 {
                    bail!("active native val_proj window has zero sampled rows");
                }
                let exact_pytorch_tbptt = pytorch_tbptt_ltm_weighting
                    .context("active native val_proj window has no sampled-weighting mode")?;
                let val_proj_scale = if exact_pytorch_tbptt {
                    alignment_weight
                } else {
                    alignment_weight / native_sampled_rows as f32 / gradient_normalization_scale
                };
                full_model_optimizer.record_scale_named_gradient(
                    commands,
                    VAL_PROJ_WEIGHT_TENSOR_NAME,
                    val_proj_scale,
                )?;
            }
            full_model_optimizer.record_step_with_inactive_names(
                commands,
                &trainables,
                hyper,
                &inactive_names,
            )
        }
    }

